(function(global){
'use strict';
const RA=global.RA=global.RA||{};
const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+(w==='unpaid worker'?'unpaid':w.toLowerCase().replaceAll(' ','-'))});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('unhurried','Unhurried is formed from un- plus hurried; it describes a pace that is calm and not rushed, or a relaxed situation with plenty of time.',[C('unhurried.s1','communication','The guide gave an unhurried explanation of the safety rules and paused for questions.','导游从容地解释了安全规则，并停下来回答问题。','an unhurried explanation; speak at an unhurried pace','形容词，指做事从容、不匆忙的。','the guide has time to explain and answer questions.','从容'),C('unhurried.s2','leisure','We spent an unhurried afternoon by the river, with no appointment to reach.','我们在河边度过了悠闲的下午，不必赶去赴约。','an unhurried afternoon/lunch; take an unhurried walk','形容词，指轻松舒适、有充足时间的。','the people can relax because nothing is pressing.','悠闲')],M('The guide gave an unhurried explanation, speaking so quickly that nobody could follow.','The guide gave an unhurried explanation, speaking calmly and leaving time for questions.','unhurried表示从容、不赶时间；飞快讲解与此相反。','meaning'),[Q(1,'An unhurried explanation is delivered…','calmly, without rushing','so fast that listeners cannot follow','only after the meeting ends','Sense 1 describes a calm pace.','meaning'),Q(2,'Why was the afternoon unhurried?','There was no appointment to reach','The river was flooding','The visitors had to catch a train immediately','Sense 2 is relaxed because time is available.','context'),Q(1,'Which phrase is natural?','an unhurried lunch','a lunch unhurriedly as adjective','an unhurriedly lunch','Unhurried is the adjective modifying lunch.','grammar'),Q(1,'Unhurried is built from…','un- plus hurried','uniform plus -ity','hurry plus the noun suffix -ness only','The prefix makes hurried negative.','word-formation')]);
P('unification','Unification is the action noun from unify, recorded in English from the mid-19th century; it means the process of joining separate states, systems, or theories into one whole.',C('unification.s1','politics','The unification of the two countries took decades of negotiation and public debate.','两国统一经历了数十年的谈判和公众讨论。','national/political unification; process of unification','名词，指把原本分开的国家、系统或理论合并为一个整体的过程。','two separate countries become one political unit.','统一'),M('The unification of the two countries created two separate governments that never cooperated.','The unification of the two countries brought their separate governments into one system.','unification指合并成一个整体，不是继续保持彼此分离。','meaning'),[Q(1,'Political unification is…','the process of joining separate states into one','a plan to keep their governments permanently separate','the uniform clothing of an army','That is the political sense.','meaning'),Q(1,'What did the unification require?','Decades of negotiation and debate','A single afternoon by the river','A medical examination','The context identifies the long political process.','context'),Q(1,'Which phrase is natural?','the unification of two countries','the unification between two country','two countries unificate','Of introduces the entities being joined.','grammar'),Q(1,'Unification is formed from…','unify plus -ication','unhurried plus -ly','unit plus the plural ending -s','The noun names the process of unifying.','word-formation')]);
P('uniform','Uniform came from Latin uniformis, “of one form,” from unus, “one,” and forma, “shape”; it names special clothing or something consistent, sometimes dull through lack of variation.',[C('uniform.s1','服装','The nurses wear a blue uniform so patients can identify staff quickly.','护士穿蓝色制服，让病人能迅速辨认工作人员。','school/work uniform; wear a uniform','名词，指某组织成员穿着的特定服装。','the clothing marks the nurses as staff.','制服'),C('uniform.s2','一致','The bricks are of uniform size, which makes the wall easier to build.','这些砖块大小一致，因此墙更容易砌筑。','uniform size/quality; remain uniform','形容词，指各部分或各时段相同的、一致的。','the bricks do not vary in size.','一致'),C('uniform.s3','单调','The landscape looked uniform and flat after hours of driving across the plain.','在平原上开了几个小时后，景色显得单调而平坦。','uniform and monotonous; a uniform pattern','形容词，指缺乏变化，有时因此显得乏味。','the scenery offers little variety.','单调')],M('The nurses wore a uniform, but each person was dressed in a completely unrelated costume.','The nurses wore the same blue uniform to identify themselves as hospital staff.','uniform作为服装指组织成员穿着一致的特定服饰。','meaning'),[Q(1,'A nurses uniform is…','special clothing worn by members of an organization','a rule that every brick must differ','a landscape with no roads','Sense 1 is the clothing noun.','meaning'),Q(2,'Uniform-size bricks are…','the same size throughout','all different sizes','worn by the nursing staff','Sense 2 means consistent.','context'),Q(3,'A uniform landscape may seem…','dull because it has little variation','busy with many different features','well dressed as a nurse','Sense 3 can describe monotony.','meaning'),Q(1,'Latin uniformis was built from words meaning…','one and form','not and hurry','two and join','The word refers to having one form.','word-formation')]);
P('uniformitarianism','Uniformitarianism is formed from uniformitarian plus -ism; in geology it is the principle that the same gradual processes seen today shaped Earth over long periods.',C('uniformitarianism.s1','地质学','Uniformitarianism explains the valley through the same slow river erosion that can be observed today.','均变论用今天也能观察到的缓慢河流侵蚀来解释这座山谷的形成。','geological uniformitarianism; principle of uniformitarianism','名词，指地球长期由持续作用的相同自然过程塑造的地质学原理。','present-day erosion is used to explain ancient landforms.','均变论'),M('Uniformitarianism says that only one sudden worldwide flood formed every land feature.','Uniformitarianism explains ancient features through gradual processes that continue today.','均变论强调长期持续的过程，不是只靠一次突发洪水。','meaning'),[Q(1,'Uniformitarianism is a principle about…','the gradual processes that shape Earth over time','the uniform clothes geologists wear','how to unite two countries','That is the geological theory.','meaning'),Q(1,'How does the theory explain the valley?','By comparing it with river erosion seen today','By claiming the valley is a university','By treating the valley as a uniform','The context applies present processes to an old feature.','context'),Q(1,'Which phrase is natural?','the principle of uniformitarianism','a uniformitarianism principle ofly','the uniformitarianism are gradual','Of links the principle to the theory.','grammar'),Q(1,'The ending -ism forms…','a doctrine or system of ideas','a person who wears a uniform','an adverb of manner','It names a geological principle.','word-formation')]);
P('uniformity','Uniformity is formed from uniform plus -ity; it means sameness of form, quality, or practice, with little or no variation.',C('uniformity.s1','一致性','The factory checks the uniformity of each batch so every tile has the same thickness.','工厂检查每批产品的一致性，确保每块瓷砖厚度相同。','uniformity of size/quality; lack of uniformity','名词，指形式、质量或做法上的一致和缺少变化。','the tiles are compared for sameness.','一致性'),M('The uniformity of the tiles was obvious because every tile had a different thickness.','The uniformity of the tiles was clear because they all had the same thickness.','uniformity是相同一致；厚度各不相同说明缺乏一致性。','meaning'),[Q(1,'Uniformity of tile thickness means…','the tiles have the same thickness','each tile has a different thickness','the tiles are worn by factory staff','That is the noun meaning.','meaning'),Q(1,'What did the factory check?','Whether each batch was consistent','Whether the river had eroded a valley','Whether the workers were unhurried','The context identifies the quality being checked.','context'),Q(1,'Which phrase is natural?','uniformity of color','uniformity between colorly','the uniformity are same','Of introduces the quality that is consistent.','grammar'),Q(1,'Uniformity is formed with the noun suffix…','-ity','-ly','-ed','The suffix turns uniform into a quality noun.','word-formation')]);
P('unify','Unify came through French unifier from Latin unus, “one,” plus facere, “make”; it means join separate parts into one, or make rules or systems consistent.',[C('unify.s1','合并','The leader worked to unify the provinces after years of conflict.','多年冲突后，领导人努力统一各省。','unify a country/group; unify under one leader','动词，指把分散的国家、群体或部分结合成一个整体。','the provinces are brought together politically.','合并'),C('unify.s2','使一致','The reform will unify tax rules across all regions.','这项改革将统一各地区的税收规则。','unify standards/rules; unify a system','动词，指使规则、风格或制度统一一致。','different regional rules become the same.','使一致')],M('The reform will unify the tax rules, leaving every region with a completely different standard.','The reform will unify the tax rules so the same standard applies in every region.','unify规则意味着使其一致，而非继续使用各自标准。','meaning'),[Q(1,'To unify provinces is to…','bring them together as one political unit','make their flags all different','teach them one small class','Sense 1 is political union.','meaning'),Q(2,'Unify tax rules means…','make the rules consistent across regions','make every region use unrelated rules','change the rules into uniforms','Sense 2 is standardization.','context'),Q(1,'Which pattern is correct?','unify separate groups','unify between separate groups','unify groups into separate','Unify takes the parts being joined as its object.','grammar'),Q(1,'Latin unus and facere contribute meanings of…','one and make','not and hurry','same and quality','The verb originally expressed making one.','word-formation')]);
P('unilateral','Unilateral combines Latin unus, “one,” and latus, “side”; it describes action taken by one party alone or, medically, a condition affecting one side of the body.',[C('unilateral.s1','单方面','The agency announced a unilateral change to the contract without consulting its partners.','该机构没有咨询合作方，就单方面宣布修改合同。','unilateral action/decision; act unilaterally','形容词，指由一方单独决定或实施的。','only one party makes the change.','单方面'),C('unilateral.s2','单侧的','The patient has unilateral hearing loss in the left ear.','患者左耳有单侧听力损失。','unilateral hearing loss; unilateral injury','形容词，医学上指只影响身体一侧的。','the condition is limited to one ear.','单侧')],M('The agency made a unilateral change after getting formal approval from every partner.','The agency made a unilateral change without consulting the other parties.','unilateral表示一方单独行动，得到所有伙伴共同批准则不是单方面决定。','meaning'),[Q(1,'A unilateral contract change is…','made by one party alone','approved through equal agreement by all sides','a change affecting both ears','Sense 1 concerns one-sided action.','meaning'),Q(2,'Unilateral hearing loss affects…','one side of the body or one ear','both ears equally','the whole population','Sense 2 is the medical use.','context'),Q(1,'Which phrase is natural?','a unilateral decision','a one-sidedly decision','a decision unilateralness','Unilateral is an adjective modifying decision.','grammar'),Q(1,'The Latin elements in unilateral mean…','one and side','one and form','not and known','The word describes something involving one side.','word-formation')]);
P('unimaginable','Unimaginable is formed from un- plus imaginable; it means too extreme or large for the mind to picture, often describing scale or suffering.',C('unimaginable.s1','巨大/难以想象','The earthquake caused unimaginable damage across the coastal region.','地震给沿海地区造成了难以想象的破坏。','unimaginable damage/cost; beyond imagination','形容词，指程度极端，难以在头脑中想象或估量的。','the destruction is far beyond ordinary expectations.','难以想象'),M('The earthquake caused unimaginable damage, but every building and road remained completely untouched.','The earthquake caused unimaginable damage, destroying buildings and roads across the region.','unimaginable damage应是极其严重的破坏，不是毫发无损。','meaning'),[Q(1,'Unimaginable damage is…','so severe that it is difficult to picture its scale','minor and easy to estimate','damage that was carefully planned','That is the adjective meaning.','meaning'),Q(1,'Where did the earthquake cause damage?','Across the coastal region','Only inside one classroom','At a university ceremony','The context identifies the affected area.','context'),Q(1,'Which phrase is natural?','an unimaginable cost','an unimaginablely cost','a cost unimaginable of','Unimaginable modifies the noun cost.','grammar'),Q(1,'The prefix un- in unimaginable…','makes imaginable negative','means the action happened in the past','marks a person who imagines','It reverses the adjective imaginable.','word-formation')]);
P('unimpeded','Unimpeded is formed from un- plus impeded; it describes movement or a view that is not blocked, slowed, or obstructed.',C('unimpeded.s1','视野','From the ridge, we had an unimpeded view of the entire valley.','从山脊上，我们可以毫无遮挡地俯瞰整个山谷。','unimpeded view/access/progress; pass unimpeded','形容词，指没有障碍或阻碍的。','nothing blocks the view from the ridge.','畅通无阻'),M('From the ridge we had an unimpeded view, although a tall wall blocked the entire valley.','From the ridge we had an unimpeded view because no obstacle blocked the valley.','unimpeded表示不受阻挡；高墙挡住视线与之矛盾。','meaning'),[Q(1,'An unimpeded view is…','a view with no obstacle blocking it','a view hidden completely by a wall','a view that changes color','That is the meaning in the example.','meaning'),Q(1,'What could be seen from the ridge?','The entire valley','Only the wall in front','An underground station','The context describes a clear view.','context'),Q(1,'Which phrase is natural?','traffic moved unimpeded','traffic moved impeded freely','unimpededly traffic moved','Unimpeded functions as an adjective or complement here.','grammar'),Q(1,'The prefix un- in unimpeded means…','not or lacking an obstruction','very much','again','Unimpeded means not impeded.','word-formation')]);
P('unimportant','Unimportant is formed from un- plus important; it describes a detail or matter with little value, influence, or effect in the situation.',C('unimportant.s1','次要细节','The color of the folder is unimportant; the signed form inside is what we need.','文件夹的颜色不重要；我们需要的是里面签过字的表格。','unimportant detail/factor; seem unimportant','形容词，指对当前结果影响很小、不重要的。','the document matters more than its folder color.','不重要'),M('The color of the folder is unimportant, so it determines whether the application is accepted.','The color is unimportant because the signed form determines the application decision.','unimportant表示无关紧要；决定申请结果的因素并非不重要。','meaning'),[Q(1,'If a detail is unimportant, it…','has little effect on the outcome','is the only factor that matters','cannot be described','That is the adjective meaning.','meaning'),Q(1,'What does the office need?','The signed form inside the folder','The folder color','A uniform for each applicant','The context contrasts a minor detail with the required document.','context'),Q(1,'Which sentence is correct?','The color is unimportant to the decision.','The color is unimportantly to the decision.','The decision is unimportanting the color.','Unimportant is an adjective after be.','grammar'),Q(1,'The prefix un- changes important to mean…','not important','more important','important in the past','The prefix gives the negative meaning.','word-formation')]);
P('unincorporated','Unincorporated is formed from un- plus incorporated; it describes a community without municipal incorporation or an organization not chartered as a corporation.',C('unincorporated.s1','行政区划','They live in an unincorporated community outside the city, so county services handle local roads.','他们住在市外一个未建制社区，因此当地道路由县级部门管理。','unincorporated community/area; unincorporated territory','形容词，指未获得正式市政建制或法人注册的。','the area is outside the city government.','未建制'),M('They live in an unincorporated community that has its own incorporated city council and municipal government.','They live in an unincorporated community governed by the county rather than a city.','unincorporated community尚未形成市政法人建制，不会有自己的市政府。','meaning'),[Q(1,'An unincorporated community is…','not formally organized as a municipality','a city with its own incorporated government','a group wearing identical uniforms','That is the local-government use.','meaning'),Q(1,'Who handles the roads in the example?','County services','The city council in the community','A school tutor','The context states county services are responsible.','context'),Q(1,'Which phrase is natural?','an unincorporated area outside the city','an unincorporated outside city area of','an incorporation area outside','The adjective modifies area.','grammar'),Q(1,'The prefix un- in unincorporated means…','not incorporated','incorporated again','incorporated by one party','It negates incorporated.','word-formation')]);
P('uninformed','Uninformed is formed from un- plus informed; it means not given enough information, or having little knowledge of a subject or situation.',[C('uninformed.s1','信息不足','Residents remained uninformed about the planned water shutdown until the notice arrived.','直到通知送达，居民才得知计划中的停水安排。','remain/be uninformed about; keep someone uninformed','形容词，指没有获得有关某事的重要信息。','the residents have not been told about the shutdown.','信息不足'),C('uninformed.s2','缺乏知识','An uninformed guess about the medication could put the patient at risk.','对药物一知半解地猜测可能会使患者面临风险。','uninformed opinion/guess; uninformed about a topic','形容词，指对某一领域或情况了解不足的。','the guess is made without adequate knowledge.','缺乏知识')],M('The residents were uninformed about the shutdown because officials had explained every detail to them.','The residents were uninformed because officials had not yet explained the shutdown.','uninformed about某事表示没有得到相关信息，已充分说明就不成立。','meaning'),[Q(1,'Residents uninformed about a shutdown…','have not received enough information about it','have read and understood every notice','have shut the water off themselves','Sense 1 concerns access to information.','meaning'),Q(2,'An uninformed guess about medicine is…','made without sufficient knowledge','a conclusion based on a specialist examination','a carefully tested prescription','Sense 2 is lack of subject knowledge.','context'),Q(1,'Which phrase is standard?','uninformed about the risk','uninformed of knowing riskly','uninformed the risk about','About introduces the subject someone lacks information on.','grammar'),Q(1,'Uninformed is formed by adding un- to…','informed','formation','uniform','The prefix negates the past participle adjective.','word-formation')]);
P('uninhabitable','Uninhabitable is formed from un- plus habitable, ultimately from Latin habitare, “dwell”; it means impossible or unsafe for people to live in.',C('uninhabitable.s1','居住安全','Floodwater left the ground floor uninhabitable because the electrical system was contaminated.','洪水污染了电力系统，使底层不适合居住。','uninhabitable building/conditions; render a home uninhabitable','形容词，指人无法或不安全居住的。','the flood damage makes the floor unsafe for residents.','不适宜居住'),M('Floodwater left the ground floor uninhabitable, but it was safe and ready for residents to move back in.','Floodwater left the ground floor unsafe for residents to occupy.','uninhabitable表示不适合居住，不能同时说安全可入住。','meaning'),[Q(1,'An uninhabitable floor is…','unsafe or impossible for people to live in','fully safe and ready for residents','a floor with no furniture only','That is the meaning.','meaning'),Q(1,'Why was the ground floor uninhabitable?','Floodwater contaminated the electrical system','The room was uniform in size','The residents wanted a quiet afternoon','The context gives the safety problem.','context'),Q(1,'Which phrase is natural?','the building became uninhabitable','the building uninhabitablely became','the uninhabitable to live building','The adjective follows became as a complement.','grammar'),Q(1,'The base habitable is related to Latin habitare, meaning…','dwell or live','unite','obstruct','The word concerns whether people can live in a place.','word-formation')]);
P('uninhabited','Uninhabited is formed from un- plus inhabited; it describes a place with no human residents, without necessarily saying the place is unsafe.',C('uninhabited.s1','无人居住','The island is uninhabited except for seabirds, and no permanent settlement appears on the map.','这座岛除海鸟外无人居住，地图上也没有永久聚居点。','uninhabited island/region; remain uninhabited','形容词，指没有人居住的。','there are no human residents on the island.','无人居住'),M('The island is uninhabited, although thousands of families live there permanently.','The island is uninhabited, with no permanent human residents.','uninhabited表示没有人居住，与大量家庭定居相矛盾。','meaning'),[Q(1,'An uninhabited island has…','no human residents','no animals of any kind','no land above sea level','That is the word meaning.','meaning'),Q(1,'Who lives on the example island?','Seabirds, but no permanent human residents','Several thousand families','A university staff','The context distinguishes wildlife from human settlement.','context'),Q(1,'Which phrase is natural?','an uninhabited island','an uninhabitedly island','an inhabit island without','The adjective modifies island.','grammar'),Q(1,'The prefix un- in uninhabited means…','not inhabited','inhabited by one person','inhabited in the future','It negates the adjective inhabited.','word-formation')]);
P('uninhibited','Uninhibited is formed from un- plus inhibited; it describes free, unselfconscious behavior, or something not restrained by rules or self-control.',[C('uninhibited.s1','自由表达','The crowd was uninhibited in its celebration, dancing and singing in the town square.','人群在广场上尽情跳舞、唱歌，毫不拘束地庆祝。','uninhibited celebration/laughter; behave uninhibitedly','形容词，指行为自然放松、不担心他人评价的。','the celebrants express themselves freely.','无拘无束'),C('uninhibited.s2','不受抑制','Her uninhibited reaction surprised the host, who had expected a quiet response.','她不加克制的反应让主人吃了一惊，因为主人原以为她会安静回应。','uninhibited reaction/behavior; uninhibited by rules','形容词，指没有被规则或自我克制压住的。','the reaction is not held back.','不受抑制')],M('The crowd was uninhibited in its celebration, standing silently and hiding every reaction.','The crowd was uninhibited, dancing and singing freely in the square.','uninhibited表示不受拘束；沉默压抑与此相反。','meaning'),[Q(1,'An uninhibited celebration is…','free and unselfconscious','strictly controlled and silent','a meeting with no participants','Sense 1 describes free behavior.','meaning'),Q(2,'Why did the reaction surprise the host?','It was not held back as expected','It followed every expected quiet response','It was completely unobservable','Sense 2 is the unrestrained reaction.','context'),Q(1,'Which phrase is natural?','uninhibited laughter','uninhibition laughterly','laugh uninhibited at of','Uninhibited modifies the noun laughter.','grammar'),Q(1,'The prefix un- in uninhibited…','removes the restraint expressed by inhibited','means slightly inhibited','turns the word into a noun','It gives the opposite sense of inhibited.','word-formation')]);
P('uninspired','Uninspired is formed from un- plus inspired; it describes work that lacks originality or enthusiasm, or a person who is not showing creative energy.',C('uninspired.s1','创意不足','The sequel was technically polished but uninspired, repeating the first film without fresh ideas.','续集制作精良却缺乏创意，只是重复第一部电影，没有新点子。','uninspired design/performance; feel uninspired','形容词，指缺乏新意、热情或创作灵感的。','the work repeats old ideas rather than adding new ones.','缺乏创意'),M('The sequel was uninspired because it introduced a startlingly original story and fresh ideas.','The sequel was uninspired because it repeated the old story without fresh ideas.','uninspired表示缺乏新意，而全新原创的故事与之相反。','meaning'),[Q(1,'An uninspired sequel…','lacks fresh ideas or creative energy','is unusually original and inventive','has no film crew','That is the adjective meaning.','meaning'),Q(1,'What made the sequel uninspired?','It repeated the first film without fresh ideas','It was technically polished','It was filmed on an uninhabited island','The context identifies the lack of originality.','context'),Q(1,'Which phrase is natural?','an uninspired design','an uninspiringly design','design uninspiredness of','Uninspired is an adjective modifying design.','grammar'),Q(1,'The prefix un- in uninspired…','negates inspired','means inspired again','marks a person who inspires others','The adjective describes a lack of inspiration.','word-formation')]);
P('unintentional','Unintentional is formed from un- plus intentional; it describes something not planned or not done on purpose.',C('unintentional.s1','非故意','The damage was unintentional, but the contractor still repaired the broken pipe.','损坏并非故意造成，但承包商仍修好了破裂的管道。','unintentional damage/error; an unintentional result','形容词，指没有计划或不是有意做出的。','the damage happened without deliberate intent.','非故意'),M('The damage was unintentional because the contractor deliberately broke the pipe.','The damage was unintentional because the pipe broke by accident.','unintentional表示非故意；蓄意破坏与之相反。','meaning'),[Q(1,'Unintentional damage is…','damage that was not done on purpose','damage deliberately planned in advance','damage that cannot be repaired','That is the adjective meaning.','meaning'),Q(1,'What happened after the accidental damage?','The contractor repaired the pipe','The contractor hid the pipe','The pipe became a uniform','The context states the response.','context'),Q(1,'Which phrase is natural?','an unintentional error','an unintentionally error','an error unintentionalness','Unintentional is an adjective before the noun.','grammar'),Q(1,'Unintentional is formed from…','un- plus intentional','intent plus the adverb ending -ly','in- plus uniform','The negative prefix reverses intentional.','word-formation')]);
P('unintentionally','Unintentionally is formed from unintentional plus -ly; it means without meaning or planning to do something.',C('unintentionally.s1','意外泄露','He unintentionally revealed the plan when he mentioned the meeting in public.','他在公共场合提到那场会议时，无意中泄露了计划。','unintentionally reveal/disclose; act unintentionally','副词，指并非有意或事先计划地做某事。','the speaker discloses the information by accident.','无意地'),M('He unintentionally revealed the plan after deciding in advance to disclose it publicly.','He unintentionally revealed the plan without meaning to disclose it.','unintentionally表示无意地，事先决定公开则是有意行为。','meaning'),[Q(1,'He unintentionally revealed the plan means…','he disclosed it without meaning to','he planned a public announcement','he kept it completely secret','That is the adverb meaning.','meaning'),Q(1,'How was the plan revealed?','He mentioned the meeting in public','He sent a sealed letter to one person','He removed the meeting from the calendar','The context explains the accidental disclosure.','context'),Q(1,'Which sentence uses the adverb correctly?','She unintentionally sent the draft to the whole team.','She sent an unintentionally draft to the whole team.','She unintentionallyly sent the draft.','The adverb modifies the verb sent.','grammar'),Q(1,'Unintentionally is formed from…','unintentional plus -ly','unite plus -ion','intentional plus the plural -s','The suffix turns the adjective into an adverb.','word-formation')]);
P('uninteresting','Uninteresting is formed from un- plus interesting; it describes something boring because it fails to attract attention or curiosity.',C('uninteresting.s1','乏味','The lecture became uninteresting when the speaker repeated the same examples for an hour.','讲者把同样的例子重复了一小时，讲座因此变得乏味。','uninteresting lecture/topic; find something uninteresting','形容词，指不能引起兴趣、令人觉得无聊的。','the repetition fails to hold the audience attention.','乏味'),M('The lecture was uninteresting because everyone was fascinated and eager to hear more.','The lecture was uninteresting because the repeated examples failed to hold attention.','uninteresting表示乏味、不能引起兴趣，与听众着迷相反。','meaning'),[Q(1,'An uninteresting lecture is…','boring and unable to hold attention','so engaging that listeners want more','a lesson taught to one student','That is the adjective meaning.','meaning'),Q(1,'Why did the lecture become uninteresting?','The speaker repeated the same examples','The speaker changed topics often','The class ended early','The context names the source of boredom.','context'),Q(1,'Which phrase is natural?','an uninteresting topic','an uninterestingly topic','a topic uninterestingness','Uninteresting is an adjective modifying topic.','grammar'),Q(1,'The prefix un- in uninteresting…','makes interesting negative','means interesting again','indicates a past action','It describes the absence of interest.','word-formation')]);
P('uninterrupted','Uninterrupted is formed from un- plus interrupted; it describes time or activity that continues without pauses or disturbances.',C('uninterrupted.s1','连续时间','She worked for three uninterrupted hours before taking a short break.','她连续工作了三个小时，然后才短暂休息。','uninterrupted sleep/work; an uninterrupted period','形容词，指没有停顿或打扰、持续进行的。','no break occurs during the three-hour period.','连续不断'),M('She had three uninterrupted hours of work, with a phone call stopping her every few minutes.','She had three uninterrupted hours of work without calls or breaks.','uninterrupted表示没有中断，频繁来电会打断工作。','meaning'),[Q(1,'Three uninterrupted hours means…','three hours with no pause or disturbance','three hours split by many interruptions','a three-hour lecture that was boring','That is the adjective meaning.','meaning'),Q(1,'When did she take a break?','After the three-hour work period','Every few minutes','Before she began work','The context gives the sequence.','context'),Q(1,'Which phrase is natural?','uninterrupted sleep','uninterruptedly sleep','sleep without uninterruptedly','Uninterrupted modifies the noun sleep.','grammar'),Q(1,'The prefix un- in uninterrupted means…','not interrupted','interrupted again','interrupting in the future','It negates the state interrupted.','word-formation')]);
P('union','Union comes through Old French from Latin unio, “oneness,” from unus, “one”; it can mean a workers organization, the act or result of joining, or a marriage.',[C('union.s1','劳动组织','The warehouse union negotiated safer shifts and a written agreement about pay.','仓库工会就更安全的轮班安排和书面薪酬协议进行了谈判。','join/form a union; trade union','名词，指维护工人薪资和工作条件的组织。','the organization represents workers in negotiations.','工会'),C('union.s2','联合','The union of the two firms created a single company with offices in both cities.','两家公司的合并形成了一家在两座城市设有办公室的公司。','union of two groups; form a union','名词，指联合的行为或联合形成的整体。','separate firms are brought together.','联合'),C('union.s3','婚姻','Their union lasted fifty years, and the family celebrated the anniversary together.','他们的婚姻持续了五十年，全家一起庆祝了这个纪念日。','a lasting union; marital union','名词，正式或略显古旧地指婚姻关系。','the phrase refers to their marriage.','婚姻')],M('The warehouse union negotiated for workers, but it represented only the company owners.','The warehouse union negotiated for workers about pay and working conditions.','工会代表工人，不是代表雇主与自己谈判。','meaning'),[Q(1,'A workers union is…','an organization that protects pay and working conditions','a company merger','a measurement such as a metre','Sense 1 is the labor organization.','meaning'),Q(2,'The union of two firms means…','they joined into one company','they signed a marriage certificate','they remained entirely separate','Sense 2 is joining into a single group.','context'),Q(3,'Their union lasted fifty years refers to…','their marriage','their workplace organization','their measurement system','Sense 3 is the formal sense of marriage.','meaning'),Q(1,'The Latin source unio is associated with…','oneness','lawfulness','knowledge','The word family centers on joining as one.','word-formation')]);
P('unionization','Unionization is formed from unionize plus -ation; it means the process of organizing workers into or bringing them into a labor union.',C('unionization.s1','劳动组织','Unionization gave the warehouse staff a contract that set pay scales and safety rules.','工会化让仓库员工获得了规定薪酬等级和安全规则的合同。','unionization of workers; support unionization','名词，指使工人加入或组建工会的过程。','the staff become organized through a labor union.','工会化'),M('Unionization gave the workers a contract, although no one joined or formed a labor union.','Unionization gave the workers a contract after they organized into a labor union.','unionization就是组织工人进入工会的过程。','meaning'),[Q(1,'Unionization is the process of…','bringing workers into a labor union','joining two companies into one','making every school uniform','That is the workplace meaning.','meaning'),Q(1,'What did unionization provide in the example?','A contract covering pay and safety','A university degree','A marriage certificate','The context names the workers contract.','context'),Q(1,'Which phrase is natural?','the unionization of warehouse workers','unionization warehouse workers at','the unionization to workers are','Of introduces the workers being organized.','grammar'),Q(1,'The ending -ation forms…','a process or action noun','a negative adjective','a person who teaches privately','Unionization names a process.','word-formation')]);
P('unionize','Unionize is formed from union plus -ize; it means form or join a labor union, or organize workers into a single union.',[C('unionize.s1','加入工会','The staff voted to unionize after management cut their paid breaks.','管理层削减带薪休息时间后，员工投票决定加入工会。','vote to unionize; unionize a workplace','动词，指工人组建或加入工会。','employees choose to join a labor union.','加入工会'),C('unionize.s2','组织工会','Organizers spent a year unionizing the factories across the region.','组织者花了一年时间在该地区各工厂推动建立工会。','unionize workers/factories; campaign to unionize','动词，指把工人组织起来组成一个工会。','organizers bring separate workplaces into union organization.','组织工会')],M('The staff voted to unionize but chose to remain outside any labor organization.','The staff voted to unionize and join together in a labor organization.','unionize表示加入或组建工会，与决定不加入相矛盾。','meaning'),[Q(1,'The staff voted to unionize means they voted to…','form or join a labor union','sell the factory','make their work clothes identical','Sense 1 is the employee action.','meaning'),Q(2,'Organizers were unionizing factories by…','organizing workers into a union','removing all worker representation','giving every worker a uniform','Sense 2 focuses on organizers bringing workers together.','context'),Q(1,'Which construction is correct?','workers voted to unionize','workers voted unionizing for','workers unionize to voted','To unionize follows the verb vote.','grammar'),Q(1,'The suffix -ize commonly forms…','a verb meaning make or organize','a noun meaning a place','an adverb of manner','Unionize is the verb built from union.','word-formation')]);
P('unique','Unique came through French from Latin unicus, “only one”; it means the only one of its kind, or very distinctive and easy to recognize.',[C('unique.s1','独一无二','Each person has a unique fingerprint that can distinguish them from everyone else.','每个人都有独一无二的指纹，可以与其他人区分开。','unique fingerprint/specimen; truly unique','形容词，指同类中只有一个、无可替代的。','no other person has the same fingerprint.','独一无二'),C('unique.s2','独特','The city has a unique character created by its canals and old markets.','这座城市的运河和老市场造就了它鲜明独特的个性。','unique character/style; a unique feature','形容词，指非常特别、容易与其他事物区分的。','the combination gives the city a distinctive identity.','独特')],M('Each person has a unique fingerprint, exactly identical to the fingerprints of every other person.','Each person has a unique fingerprint that differs from every other fingerprint.','unique表示独一无二，不能同时说与所有人完全相同。','meaning'),[Q(1,'A unique fingerprint is…','the only one of its kind for that person','identical to every other fingerprint','a fingerprint used as a measurement unit','Sense 1 is uniqueness in the strict sense.','meaning'),Q(2,'What gives the city its unique character?','Its canals and old markets','Its identical streets and buildings','Its university uniform','Sense 2 means distinctive.','context'),Q(1,'Which phrase is natural?','a unique style','a uniquely style','a style uniqueness','Unique is the adjective before style.','grammar'),Q(1,'Latin unicus meant…','only one','not lawful','uninterrupted','Unique developed from the idea of one alone.','word-formation')]);
P('uniquely','Uniquely is formed from unique plus -ly; it means in a distinctive way, and can also mean solely or in a way that belongs to one person or thing.',[C('uniquely.s1','独特地/专属地','The site is uniquely placed beside the fault, making it ideal for monitoring small tremors.','该地点独特地位于断层旁，非常适合监测微小震动。','uniquely suited/placed; uniquely positioned','副词，指以独特方式，或具有某种专属的位置或条件。','the location has an uncommon advantage.','独特地'),C('uniquely.s1','仅仅','The authority is uniquely responsible for issuing the final permit.','该主管机关是唯一负责签发最终许可证的机构。','uniquely responsible/qualified; uniquely belongs to','副词，可表示只有某人或某物承担或具备某事。','no other body has the stated responsibility.','唯一地')],M('The site is uniquely placed beside the fault, in exactly the same position as every other monitoring station.','The site is uniquely placed beside the fault, unlike the other monitoring stations.','uniquely placed表示位置具有独特性，不能同时说与所有其他站点完全相同。','meaning'),[Q(1,'A site uniquely placed beside a fault is…','distinctively positioned there','located in exactly the same place as every other site','unlawful to enter','Sense 1 concerns a special position.','meaning'),Q(1,'The authority is uniquely responsible means…','only that authority has the responsibility','every authority has equal responsibility','no one has the responsibility','This question tests the adverb meaning “solely.”','context'),Q(1,'Which phrase uses the adverb correctly?','uniquely suited to the task','a uniquely solution','suitability uniquely task','Uniquely modifies the adjective suited.','grammar'),Q(1,'Uniquely is formed by adding -ly to…','unique','unit','union','The suffix forms an adverb from the adjective.','word-formation')]);
P('uniqueness','Uniqueness is formed from unique plus -ness; it means the state or quality of being unlike anything else.',C('uniqueness.s1','独特性','The report stressed the uniqueness of the dialect, which preserves several sounds lost elsewhere.','报告强调了这种方言的独特性，它保留了其他地方已经消失的几种发音。','uniqueness of a design/dialect; preserve uniqueness','名词，指与其他事物不同、无可比拟的特质。','the dialect retains sounds that distinguish it.','独特性'),M('The report stressed the dialects uniqueness, although every sound and feature was identical to all neighboring dialects.','The report stressed the dialects uniqueness because it preserves sounds found nowhere nearby.','独特性意味着存在可辨别差异，而不是与邻近方言完全一致。','meaning'),[Q(1,'The uniqueness of a dialect is…','the quality that makes it unlike others','the fact that it copies every neighboring dialect','a class section in a book','That is the noun meaning.','meaning'),Q(1,'What makes the dialect distinctive?','It preserves sounds lost elsewhere','It uses no sounds','It has a uniform school outfit','The context names the unusual feature.','context'),Q(1,'Which phrase is natural?','the uniqueness of the design','the unique of the designness','uniquely the design of','Of introduces what has the quality.','grammar'),Q(1,'The suffix -ness forms…','a noun naming a state or quality','a verb meaning to join','a negative adjective','It turns unique into the quality noun uniqueness.','word-formation')]);
P('unit','Unit comes from Latin unitas, “oneness,” through French; it means a fixed measure, one section of a course or building, or a device or small working group.',[C('unit.s1','计量单位','The metre is the standard unit of length used in the laboratory.','米是实验室使用的标准长度单位。','unit of measurement; SI unit','名词，指测量某种数量时采用的固定标准。','the metre provides a fixed standard for length.','计量单位'),C('unit.s2','课程/建筑单元','We finished Unit 3 yesterday and began the next section of the textbook today.','我们昨天完成了教材第三单元，今天开始下一部分。','a unit of a course/book; housing unit','名词，指课程、书籍或建筑中的一个部分。','Unit 3 is one section in a larger course.','单元'),C('unit.s3','设备/小组','The intensive care unit is full, so the hospital is moving two patients to another ward.','重症监护室已经满员，医院正把两名患者转到其他病房。','a machine/control unit; a medical unit','名词，可指设备、机器部件或执行特定工作的组织小组。','the hospital unit is a working section of the institution.','部门/设备')],M('The metre is a unit of length, but it is an unrelated song title and cannot measure distance.','The metre is a unit of length and gives a standard for measuring distance.','unit在该语境中表示计量标准，不是歌曲名称。','meaning'),[Q(1,'A metre as a unit is…','a fixed standard for measuring length','a section of a novel','a hospital team','Sense 1 is measurement.','meaning'),Q(2,'Unit 3 in a textbook is…','one section of a larger course or book','a length standard','a machine engine','Sense 2 is a section.','context'),Q(3,'An intensive care unit is…','a hospital department or working section','a unit used to measure distance','a school uniform','Sense 3 is an organizational section.','meaning'),Q(1,'Which phrase is natural?','a unit of length','a length uniting of','a unit lengthly','Of identifies the quantity measured.','grammar')]);
P('unite','Unite comes from Latin unire, “make one,” from unus, “one”; it means join with others for a shared aim or combine separate parts into one organization or country.',[C('unite.s1','团结合作','The villages united against the flood and shared boats, food, and rescue teams.','洪水来袭时，各村团结起来，共享船只、食物和救援队。','unite against a threat; unite for a cause','动词，指人们为共同目标联合行动。','the villages cooperate in response to danger.','团结'),C('unite.s2','合并','The treaty united the two states under one government.','条约使两个州在一个政府下合并起来。','unite two states/groups; unite into one','动词，指把分散的部分合并成一个国家或组织。','separate political units become one.','合并')],M('The villages united against the flood by refusing to share any boats or rescue teams.','The villages united against the flood and coordinated their rescue resources.','unite for共同目标意味着联合协作，拒绝合作与之相反。','meaning'),[Q(1,'The villages united against the flood means they…','worked together toward a shared aim','refused to cooperate with one another','joined a labor union for better pay','Sense 1 is collective action.','meaning'),Q(2,'The treaty united two states means it…','combined them under one government','kept them politically separate','made their uniforms identical','Sense 2 is political merger.','context'),Q(1,'Which construction is correct?','unite against a common threat','unite to against a common threat','unite a common threat against','Against introduces the shared opponent.','grammar'),Q(1,'Latin unire meant…','make one','measure length','act unfairly','The verb means joining into one.','word-formation')]);
P('united','United is the past participle of unite; it means joined into one body or organization, or agreed by every member of a group.',[C('united.s1','合并成整体','The two firms operated as a united company after completing the merger.','合并完成后，两家公司以一家联合公司的形式运营。','united company/front; remain united','形容词，指结合成一个整体或共同组织的。','the firms now operate as one company.','合并'),C('united.s2','一致同意','The council issued a united statement supporting the safety plan.','委员会发表了一份一致支持安全计划的声明。','a united statement/voice; stand united','形容词，指团体所有成员意见一致的。','all members support the statement.','一致同意')],M('The council issued a united statement, although every member publicly rejected the plan.','The council issued a united statement because all members supported the plan.','united statement表示意见一致，成员全体反对与之矛盾。','meaning'),[Q(1,'A united company is…','formed by organizations joined into one','a company divided into unrelated firms','a unit of measurement','Sense 1 is merger.','meaning'),Q(2,'A united statement from a council shows…','agreement among all members','that each member rejected it','that no statement was issued','Sense 2 is consensus.','context'),Q(1,'Which phrase is natural?','the two firms became united','the two firms unitedly became','the united two firms into','United can follow became as an adjective.','grammar'),Q(1,'United is the past participle of…','unite','unit','uniform','It describes the resulting state after joining.','word-formation')]);
P('unity','Unity comes through Old French unite from Latin unitas, “oneness”; it means people or parts joined and acting as one, or the completeness of a whole.',[C('unity.s1','团结','The crisis restored a sense of unity to the party, and members began working together again.','危机让该党恢复了团结感，成员们重新开始协作。','national/party unity; promote unity','名词，指群体团结一致、共同采取行动的状态。','members cooperate rather than compete.','团结'),C('unity.s2','整体性','The artist valued unity above detail, arranging every shape to support the whole composition.','这位艺术家把整体性看得高于细节，让每个形状都服务于整幅作品。','unity of design; a sense of unity','名词，指各部分构成连贯完整整体的状态。','the parts work together as one composition.','整体性')],M('The crisis restored unity to the party, with every member refusing to cooperate with the others.','The crisis restored unity to the party, and members began cooperating again.','unity表示团结一致，成员拒绝合作与之相反。','meaning'),[Q(1,'Unity in a political party means…','members are joined and act together','members compete without communication','the party wears one uniform','Sense 1 concerns group solidarity.','meaning'),Q(2,'Unity in a composition means…','the parts form a coherent whole','every detail is unrelated','the artist joined a labor union','Sense 2 is artistic wholeness.','context'),Q(1,'Which phrase is natural?','a sense of unity among members','a unity members sense ofly','the unity are joined together','Among identifies the group sharing the quality.','grammar'),Q(1,'Latin unitas meant…','oneness','not lawful','a university teacher','Unity is the state of being one.','word-formation')]);
P('universal','Universal comes from Latin universalis, from universus, “whole or entire”; it means valid in every case or available to everyone, and can refer to the whole universe or world.',[C('universal.s1','普遍适用','The clinic offers universal access to clean water for every household in the district.','诊所为该地区每户家庭提供普遍的清洁水服务。','universal access/coverage; universal rule','形容词，指对所有人或所有情况都适用、开放的。','every household can use the service.','普遍的'),C('universal.s2','宇宙/世界范围','Astronomers study universal processes such as the formation of stars and galaxies.','天文学家研究恒星和星系形成等宇宙过程。','universal scale; universal processes','形容词，指与整个宇宙或全世界有关的。','the processes concern the universe at large.','宇宙的')],M('The clinic offers universal access to water, but only one household in the district may use it.','The clinic offers universal access so every household may use the clean water.','universal access意味着所有人都可使用，不能只限一家。','meaning'),[Q(1,'Universal access to water means…','everyone in the stated group can access it','only one household can use it','the water exists only in space','Sense 1 means available to all.','meaning'),Q(2,'Universal processes in astronomy concern…','the universe as a whole','a single local clinic only','a worker union','Sense 2 is cosmic scope.','context'),Q(1,'Which phrase is natural?','a universal rule','a universally rule','a rule universalness','Universal is the adjective before the noun.','grammar'),Q(1,'Latin universus meant…','whole or entire','one-sided','not obstructed','The adjective refers to an entire group or whole.','word-formation')]);
P('universality','Universality is formed from universal plus -ity; it means the state of being true, present, or applicable everywhere or for all people.',C('universality.s1','普遍性','The experiment was designed to test the universality of the rule across several languages.','这项实验旨在检验该规则在多种语言中的普遍性。','universality of a principle; question its universality','名词，指对所有人或所有情况普遍成立的状态。','the rule is compared across distinct languages.','普遍性'),M('The experiment tested the universality of the rule, but it worked in every case without exception.','The experiment questioned universality because the rule failed in several languages.','若规则在所有情况下都有效，就不会因实验而质疑其普遍性。','meaning'),[Q(1,'The universality of a rule is…','its being valid across cases or groups','its failure in every case','its use by one person only','That is the noun meaning.','meaning'),Q(1,'What did the experiment compare?','How the rule worked across several languages','The sizes of two uniforms','The price of university tuition','The context shows a cross-language test.','context'),Q(1,'Which phrase is natural?','test the universality of the principle','test universally the principle ofity','universality test the principle to','Of introduces what is being tested.','grammar'),Q(1,'The suffix -ity forms…','a noun naming a state or quality','a verb meaning make one','an adverb meaning everywhere','It turns universal into a quality noun.','word-formation')]);
P('universally','Universally is formed from universal plus -ly; it means in a way that includes all people or cases, though it often appears with a negative to limit a claim.',C('universally.s1','普遍地','The method is not universally applicable because some languages lack the same sound pattern.','这种方法并非普遍适用，因为有些语言没有相同的语音模式。','universally accepted/applicable; apply universally','副词，指对所有人、地方或情况都适用地。','the method does not work in every language.','普遍地'),M('The method is not universally applicable, yet it works without exception in every language.','The method is not universally applicable because some languages lack the required pattern.','not universally applicable与毫无例外地处处适用相矛盾。','meaning'),[Q(1,'Not universally applicable means…','it does not work in every case','it works in every possible case','it is a unit of measurement','That is the meaning in the example.','meaning'),Q(1,'Why does the method have limits?','Some languages lack the sound pattern','Every language shares that pattern','The rule has universal acceptance','The context provides the limitation.','context'),Q(1,'Which sentence uses universally correctly?','The policy is not universally accepted.','The universally policy is acceptedly.','The policy universally is accept.','Universally modifies the participle accepted.','grammar'),Q(1,'Universally is formed from…','universal plus -ly','universe plus -ful','unify plus -ation','The suffix forms an adverb from universal.','word-formation')]);
P('universe','Universe comes through Old French from Latin universum, “all things or the whole”; it means all space, time, matter, and energy, or a complete set within one area of life.',[C('universe.s1','宇宙','Astronomers are still investigating how the universe began and how it continues to expand.','天文学家仍在研究宇宙如何起源以及它如何继续膨胀。','the observable universe; origin of the universe','名词，指包括空间、时间、物质和能量在内的整体。','the question concerns all cosmic space and matter.','宇宙'),C('universe.s2','完整范围','After years in the countryside, the city changed her universe of friends, work, and daily routines.','在乡村生活多年后，这座城市改变了她的朋友圈、工作和日常生活范围。','a universe of choices; change someones universe','名词，比喻某一生活领域中完整的一组事物。','the word refers broadly to her social and daily world.','生活范围')],M('Astronomers study the universe, which consists only of one small planet and excludes all space and matter.','Astronomers study the universe, including all space, time, matter, and energy.','universe指整体宇宙，不仅仅是一颗行星。','meaning'),[Q(1,'The universe in astronomy includes…','all space, time, matter, and energy','only one planet','one section of a textbook','Sense 1 is the cosmic whole.','meaning'),Q(2,'Her universe of friends and routines means…','the complete set of her social and daily life','all matter in outer space','a fixed measuring quantity','Sense 2 is figurative.','context'),Q(1,'Which phrase is natural?','the origin of the universe','the universe originly of','an universe of origin','The phrase uses the before universe.','grammar'),Q(1,'Latin universum referred to…','all things as a whole','one side of the body','not knowing','The word developed from the idea of the entire whole.','word-formation')]);
P('university','University came through Old French from Latin universitas, “the whole or a corporate body”; it names a degree-granting institution and can refer collectively to its students and teachers.',[C('university.s1','高等教育','She studies biology at a university that also funds research in public health.','她在一所大学学习生物学，该校还资助公共卫生研究。','attend/go to a university; university degree','名词，指提供高等教育学位并开展研究的机构。','students study for degrees and staff conduct research.','大学'),C('university.s2','师生群体','The university will close for the holiday, and its students and teachers will leave campus.','大学将在假期关闭，师生将离开校园。','the university decided/announced; university staff','名词，可集合地指该校的师生或管理群体。','the institution speaks and acts through its people.','大学群体')],M('She studies at a university, which is a primary school for children learning their first alphabet.','She studies at a degree-granting institution for higher education.','university指高等教育机构，不是小学。','meaning'),[Q(1,'A university is an institution where people…','study for degrees and conduct research','learn only their first alphabet','receive a fixed unit of length','Sense 1 describes higher education.','meaning'),Q(2,'The university will close for the holiday means…','the institution and its people will stop operating','the building will become a universe','only one student will leave','Sense 2 can refer collectively to the institution community.','context'),Q(1,'Which phrase is standard?','study at a university','study a university at','study in universitying','At is natural for attending an institution.','grammar'),Q(1,'The Latin source universitas referred to…','a whole or corporate body','a single side','an unplanned action','The institution name reflects an organized academic community.','word-formation')]);
P('unjust','Unjust is formed from un- plus just, from Latin iustus, “lawful or fair”; it describes treatment or a decision that is not fair, especially when made by someone in power.',C('unjust.s1','不公正','He received an unjust punishment because the committee ignored the evidence in his favor.','他受到了不公正的惩罚，因为委员会忽略了对他有利的证据。','unjust law/punishment; treat someone unjustly','形容词，指不公平、尤其是不公正对待他人的。','the decision disregards relevant evidence.','不公正'),M('He received an unjust punishment after the committee fairly considered all evidence and treated everyone equally.','He received an unjust punishment because the committee ignored evidence in his favor.','unjust描述不公平对待，与公平审理证据相反。','meaning'),[Q(1,'An unjust punishment is…','not fair to the person receiving it','fairly based on all relevant evidence','a punishment for wearing a uniform','That is the adjective meaning.','meaning'),Q(1,'Why was the punishment unjust?','The committee ignored evidence in his favor','The committee reviewed all evidence fairly','The punishment was discussed at a university','The context states the unfair procedure.','context'),Q(1,'Which phrase is natural?','an unjust decision','an injustice decision','a decision unjustlyness','Unjust is an adjective modifying decision.','grammar'),Q(1,'The prefix un- in unjust…','negates just','means just once','forms an adverb','It gives the opposite of fair.','word-formation')]);
P('unkind','Unkind is formed from un- plus kind; it means not pleasant or friendly, especially in a way that hurts another person.',C('unkind.s1','不友善','It is unkind to laugh at a classmate who is struggling to read aloud.','嘲笑一个朗读吃力的同学是不友善的。','unkind remark/treatment; be unkind to someone','形容词，指不友好、会使他人难过的。','the laughter embarrasses a classmate.','不友善'),M('It was unkind to laugh at the classmate, and the laughter made him feel warmly supported.','It was unkind to laugh at the classmate because it embarrassed him.','嘲笑使人难堪是伤人的行为，不是给予支持。','meaning'),[Q(1,'An unkind remark is…','a comment likely to hurt someone','a supportive comment that comforts them','a fair legal decision','That is the adjective meaning.','meaning'),Q(1,'Why was laughing at the classmate unkind?','He was struggling and felt embarrassed','He had just won a prize','The class was discussing a university','The context identifies the hurtful situation.','context'),Q(1,'Which phrase is natural?','unkind to a classmate','unkind for a classmate toly','a classmate unkindness to','To introduces the person affected.','grammar'),Q(1,'Unkind is formed from…','un- plus kind','union plus -ize','universe plus -al','The negative prefix gives the opposite of kind.','word-formation')]);
P('unknowing','Unknowing is formed from un- plus knowing; it describes someone lacking awareness or knowledge, sometimes without realizing they are involved in something.',C('unknowing.s1','不知情','He became an unknowing carrier of the rumor after repeating a false story he believed.','他相信了一个假故事并转述后，在不知情中成了谣言的传播者。','an unknowing participant/carrier; remain unknowing','形容词，指缺乏相关知识或没有意识到某种情况的。','he passes on the rumor without realizing it is false.','不知情'),M('He was an unknowing carrier of the rumor, although he knew it was false and spread it deliberately.','He was an unknowing carrier because he repeated the story without knowing it was false.','unknowing表示缺乏意识或知识，与明知而故意传播相反。','meaning'),[Q(1,'An unknowing carrier of a rumor…','passes it on without realizing the truth','knows it is false and spreads it on purpose','is responsible for the legal ruling','That is the meaning of unknowing.','meaning'),Q(1,'Why was he unknowing?','He believed the false story when repeating it','He checked the original evidence first','He announced the rumor publicly on purpose','The context explains his lack of awareness.','context'),Q(1,'Which phrase is natural?','an unknowing participant','an unknowingly participant','a participant unknowingness','Unknowing is an adjective before participant.','grammar'),Q(1,'The prefix un- in unknowing…','means lacking knowledge or awareness','means knowing very well','marks an action done in the past','It negates knowing.','word-formation')]);
P('unknown','Unknown is formed from un- plus known; it means not identified or not known, not famous, and can be a noun for an unidentified person.',[C('unknown.s1','未查明','The cause of the equipment failure is still unknown, so the engineers are testing the power supply.','设备故障原因仍未查明，因此工程师正在检测电源。','unknown cause/quantity; remain unknown','形容词，指尚未知道或辨认出来的。','the engineers have not identified the cause.','未知'),C('unknown.s2','不出名','She was unknown outside her own country before the novel became an international success.','这部小说在国际上走红前，她在本国以外并不出名。','unknown writer/artist; remain unknown','形容词，指不为很多人所知、没有名气的。','few people abroad knew of the writer.','不出名'),C('unknown.s3','身份不明者','The letter came from an unknown who used no name or return address.','这封信来自一位身份不明的人，没有署名或回邮地址。','an unknown sender; an unknown in the case','名词，指姓名或身份没有被确认的人。','the person cannot be identified.','身份不明者')],M('The cause is unknown, and the engineers have already identified it with certainty.','The cause is unknown because the engineers have not identified it yet.','unknown意味着尚未查明，已确定身份则与之矛盾。','meaning'),[Q(1,'An unknown cause is…','a cause that has not been identified','a famous cause recognized by everyone','a standardized unit','Sense 1 is lack of knowledge.','meaning'),Q(2,'She was unknown outside her country means…','few people abroad knew of her','she was internationally famous','she had an unidentified sender','Sense 2 is lack of fame.','context'),Q(3,'An unknown who sent a letter is…','a person whose identity is not known','a famous author','a known university student','Sense 3 is the noun use.','meaning'),Q(1,'Unknown is formed from…','un- plus known','known plus the suffix -ity','unit plus -own','The prefix negates known.','word-formation')]);
P('unlawful','Unlawful is formed from un- plus lawful; it means prohibited by law and can also describe conduct regarded as unacceptable by society.',[C('unlawful.s1','违法','The police stopped the unlawful assembly because the organizers had no required permit.','警方制止了这场违法集会，因为组织者没有必要的许可证。','unlawful assembly/search; declare something unlawful','形容词，指法律不允许的。','the gathering violates a legal requirement.','违法'),C('unlawful.s2','不正当','They used unlawful means to win the contract, including threats against a witness.','他们用不正当手段赢得合同，包括威胁一名证人。','unlawful means/conduct; socially unlawful','形容词，指社会认为不正当、不可接受的行为方式。','threatening a witness is unacceptable conduct.','不正当')],M('The assembly was unlawful even though it had obtained every permit required by law.','The assembly was unlawful because it lacked the required permit.','unlawful表示违反法律；已取得所需许可并不能据此判为违法。','meaning'),[Q(1,'An unlawful assembly is…','a gathering prohibited by law','a gathering that satisfies every legal requirement','a group organized into a labor union','Sense 1 is legal prohibition.','meaning'),Q(2,'Unlawful means in winning a contract are…','socially unacceptable actions such as threats','fair negotiations and open competition','a unit of measurement','Sense 2 concerns improper conduct.','context'),Q(1,'Which phrase is natural?','an unlawful search','a search unlawfullyness','a search unlegal','Unlawful modifies the noun search.','grammar'),Q(1,'The prefix un- in unlawful…','negates lawful','means lawful again','marks a person who enforces law','It forms the negative adjective.','word-formation')]);
P('unleash','Unleash combines un- with leash and means release a powerful feeling or force suddenly, or literally free an animal from its leash.',[C('unleash.s1','情绪爆发','The speech unleashed a storm of protest from workers who had waited months for a response.','演讲引发了工人的强烈抗议，他们已经等了数月却没有得到回应。','unleash anger/protests; unleash a storm of','动词，指使强烈情绪、力量或反应突然爆发。','the speech triggers a sudden wave of protest.','引发'),C('unleash.s2','松开牵引绳','Please unleash the dog in the fenced park after checking that the gate is closed.','确认大门关好后，请在围栏公园里解开狗的牵引绳。','unleash a dog; unleash from a leash','动词，指解开动物的牵引绳使其自由活动。','the dog is freed from its leash.','解开牵引绳')],M('The speech unleashed a storm of protest, but everyone stayed silent and showed no reaction.','The speech unleashed a storm of protest as workers responded angrily.','unleash a protest指引发抗议，完全沉默则没有爆发反应。','meaning'),[Q(1,'A speech unleashes protest when it…','causes a strong reaction to begin','stops every response before it starts','lets a dog out of a fenced park','Sense 1 is figurative release.','meaning'),Q(2,'To unleash the dog means…','free it from its leash','put a leash on it','take it to a lecture','Sense 2 is literal.','context'),Q(1,'Which phrase is natural?','unleash a wave of anger','unleash an anger wave into dog','unleash to a wave of anger','Unleash takes the released force as its object.','grammar'),Q(1,'Unleash is built from…','un- plus leash','unless plus -ed','universal plus -ity','The word describes taking a leash off or releasing a force.','word-formation')]);
P('unless','Unless developed from Middle English on lesse, “on a less (condition),” and introduces the condition whose absence allows something else to happen.',[C('unless.s1','条件','Unless you leave now, you will miss the last bus to the village.','除非你现在出发，否则就会错过去村里的末班车。','unless you hurry; unless otherwise stated','连词，表示如果不满足某条件，另一结果就会发生。','leaving now is necessary to catch the bus.','除非'),C('unless.s2','例外说明','The gallery is open daily unless otherwise stated on its notice board.','除非告示牌另有说明，画廊每天开放。','unless otherwise stated/noted; unless specified','连词，用于固定表达中，表示除非另有说明或例外。','the stated schedule applies except when another notice says so.','除非另有说明')],M('Unless you leave now, you will catch the last bus even though it departs before you arrive.','Unless you leave now, you will miss the last bus before it departs.','unless引入不采取行动的条件以及相应结果；原句逻辑矛盾。','meaning'),[Q(1,'Unless you leave now means…','if you do not leave now, the stated result will follow','you must leave only after the bus has gone','the bus schedule is always false','That is the conditional meaning.','meaning'),Q(2,'Open daily unless otherwise stated means…','the gallery opens daily except when a notice says differently','the gallery never opens on any day','the notice is always unnecessary','Sense 2 states an exception.','context'),Q(1,'Which sentence uses unless correctly?','Unless it rains, the match will continue.','Unless it rains, the match will continue if it does rain.','The match unless rain will continue to.','Unless introduces the condition that would change the result.','grammar'),Q(1,'The older phrase behind unless was…','on lesse, meaning on a less condition','un plus less, meaning not less','one less day of the week','Its history is from a conditional phrase, not a simple negative prefix.','word-formation')]);
P('unlike','Unlike combines un- with like and means not similar to a person or thing; it can introduce the person or thing used for comparison.',C('unlike.s1','比较','Unlike the coast, the dry interior receives little rain in summer.','与沿海不同，内陆干燥地区夏季降雨很少。','unlike its predecessor; unlike the coast','介词/形容词，表示与某人或某物不相似。','the interior is contrasted with the coast.','不同于'),M('Unlike the coast, the interior receives the same heavy rainfall every day.','Unlike the coast, the interior is dry and receives little rain.','句中用unlike作比较，但两地降雨相同不能体现差异。','meaning'),[Q(1,'Unlike the coast means…','different from the coast','exactly the same as the coast','located underneath the coast','That is the comparison meaning.','meaning'),Q(1,'How is the interior different?','It receives little summer rain','It is surrounded by ocean','It has a workers union','The context states the contrast.','context'),Q(1,'Which phrase is correct?','Unlike her brother, she enjoys hiking.','Unlike her brother, but she enjoys hiking.','She unlike enjoys her brother hiking.','Unlike introduces the comparison directly.','grammar'),Q(1,'The prefix un- in unlike contributes…','the opposite of like or similar','the sense of repeating','the sense of a place','It marks dissimilarity.','word-formation')]);
P('unlikely','Unlikely is formed from un- plus likely; it means not expected to happen, or strange enough to be hard to believe.',[C('unlikely.s1','不太可能','It is unlikely that the price will fall before the contract expires.','合同到期前价格不太可能下跌。','unlikely to happen; it is unlikely that','形容词，指某事发生的可能性不大。','the speaker expects the price to remain stable.','不太可能'),C('unlikely.s2','难以置信','He told an unlikely tale about finding a crown beneath the old bridge.','他讲了一个难以置信的故事，说自己在老桥下发现了一顶王冠。','an unlikely story/excuse; sound unlikely','形容词，指因奇怪或不寻常而难以相信的。','the story sounds improbable to listeners.','难以置信')],M('It is unlikely that the price will fall, and analysts are certain it will drop tomorrow.','It is unlikely that the price will fall, so analysts do not expect a drop.','unlikely表达可能性低，与分析师确信明天会下跌不一致。','meaning'),[Q(1,'An unlikely event is…','not expected to happen','certain to happen','already completed and recorded','Sense 1 is probability.','meaning'),Q(2,'An unlikely tale is…','strange and difficult to believe','a verified routine account','a story about a unit of length','Sense 2 is credibility.','context'),Q(1,'Which construction is natural?','It is unlikely that the price will fall.','It unlikely is that the price fall.','It is unlikely the price will falling that.','It is unlikely that is the standard clause pattern.','grammar'),Q(1,'Unlikely is formed from…','un- plus likely','likely plus the plural -s','unlike plus -able','The negative prefix lowers the likelihood.','word-formation')]);
P('unlimited','Unlimited is formed from un- plus limited; it means not restricted in amount, size, number, or access.',C('unlimited.s1','不受限制','The museum pass gives unlimited access for the whole month, with no daily entry cap.','这张博物馆通行证整月可无限次入场，没有每日次数上限。','unlimited access/data; unlimited number','形容词，指数量或使用没有规定上限的。','visitors can enter without a daily limit.','无限制'),M('The pass gives unlimited access, but it permits exactly one visit for the entire month.','The pass gives unlimited access and allows repeated visits throughout the month.','unlimited access不设次数上限，恰好只能进一次则是有限制。','meaning'),[Q(1,'Unlimited access means…','there is no stated cap on use','only one visit is allowed','access is available for one hour only','That is the adjective meaning.','meaning'),Q(1,'How often may the pass holder enter?','Repeatedly during the month','Exactly once','Only after the museum closes','The context says there is no daily cap.','context'),Q(1,'Which phrase is natural?','unlimited access to the museum','unlimitedly access to museum','access unlimitedness at museum','Unlimited modifies access.','grammar'),Q(1,'The prefix un- in unlimited means…','not limited or restricted','limited again','a very small limit','It negates limited.','word-formation')]);
P('unload','Unload is formed from un- plus load; it means remove goods from a vehicle, have goods removed from a ship, or tell someone worries to feel relief.',[C('unload.s1','卸货','Workers unloaded the truck before the market opened at dawn.','市场黎明开门前，工人们卸下了卡车上的货物。','unload a truck/container; unload goods','动词，指从车辆、船只或容器中卸下货物。','the workers remove cargo from the truck.','卸货'),C('unload.s2','船只卸货','The ship is unloading at the port, and cranes are moving boxes to the dock.','船正在港口卸货，起重机把箱子搬到码头。','a ship unloads at a port; unload at the dock','动词，指船上的货物被移出。','cargo is being taken off the vessel.','船只卸货'),C('unload.s3','倾诉','She unloaded her worries on a friend after keeping them to herself for weeks.','把烦恼憋了几周后，她向朋友倾诉了出来。','unload worries/problems on someone; unload on a friend','动词，非正式地指向别人倾诉积压的烦恼。','sharing the worries makes her feel less burdened.','倾诉')],M('Workers unloaded the truck by placing more boxes onto it and raising the cargo level.','Workers unloaded the truck by removing its cargo.','unload表示卸下货物，而不是继续往车上装货。','meaning'),[Q(1,'Workers unloaded the truck means they…','removed goods from it','added more goods to it','drove it to the market','Sense 1 is cargo removal.','meaning'),Q(2,'The ship is unloading means…','its cargo is being taken off','it is being filled with cargo','it is leaving the port empty','Sense 2 describes goods leaving the vessel.','context'),Q(3,'She unloaded her worries on a friend means she…','told the friend about them','put the friend in a truck','kept every worry secret','Sense 3 is the informal figurative use.','meaning'),Q(1,'Which phrase is natural?','unload the boxes from the truck','unload the boxes into the truck','unload from the truck the boxes to','From marks where the cargo is removed.','grammar')]);
P('unlock','Unlock combines un- with lock; it means open something secured by a lock, or figuratively discover a way to achieve or understand something new.',[C('unlock.s1','开锁','She unlocked the back door with a spare key before carrying in the groceries.','她用备用钥匙打开后门，再把食品拿进屋。','unlock a door/phone; unlock with a key','动词，指解除锁定并打开上锁的东西。','the key releases the lock.','开锁'),C('unlock.s2','解锁潜力','The new data may unlock a treatment for the rare disease.','新数据可能会帮助找到这种罕见病的治疗方法。','unlock a cure/potential; unlock new possibilities','动词，比喻找到实现或理解新事物的方法。','the data may enable researchers to make progress.','解锁潜力')],M('She unlocked the back door by turning the spare key and leaving the lock engaged.','She unlocked the back door by turning the key until the lock released.','unlock表示解除锁定，保持锁住与动作结果相反。','meaning'),[Q(1,'To unlock a door is to…','open it by releasing its lock','close it and keep it secured','remove the door from its frame','Sense 1 is literal.','meaning'),Q(2,'Data may unlock a cure means it may…','help researchers discover a treatment','put a physical key into a medicine bottle','make the disease impossible to study','Sense 2 is figurative discovery.','context'),Q(1,'Which phrase is natural?','unlock the phone with a code','unlock a code from the phone with','unlocking the phone to a code','With introduces the method used.','grammar'),Q(1,'The prefix un- in unlock means…','reverse or remove the locked state','lock again','make a lock larger','It gives the verb its opposite-action sense.','word-formation')]);
P('unmanageable','Unmanageable is formed from un- plus manageable; it means too difficult to control, organize, direct, or deal with.',C('unmanageable.s1','难以处理','The dataset became unmanageable without an index because staff could not find records reliably.','没有索引时，数据集变得难以管理，员工无法可靠地找到记录。','unmanageable workload/dataset; become unmanageable','形容词，指难以管理、控制或处理的。','the missing index makes searching impractical.','难以管理'),M('The dataset was unmanageable, and every record could be found instantly without an index.','The dataset was unmanageable because staff could not locate records without an index.','unmanageable表示难以处理，能瞬间找到所有记录与之相反。','meaning'),[Q(1,'An unmanageable dataset is…','too difficult to organize or deal with','easy to search and control','a group of workers in a union','That is the adjective meaning.','meaning'),Q(1,'Why was the dataset unmanageable?','It had no index for finding records','It had a clear index','It contained only one record','The context identifies the missing tool.','context'),Q(1,'Which phrase is natural?','an unmanageable workload','a workload unmanageably as adjective','an unmanage of workload','Unmanageable modifies workload.','grammar'),Q(1,'The prefix un- in unmanageable…','negates manageable','means manageable again','forms the past tense','It marks something that cannot be managed.','word-formation')]);
P('unmarried','Unmarried is formed from un- plus married; it describes someone who is not married, a status that may be mentioned as relevant information.',C('unmarried.s1','婚姻状态','He was still unmarried at forty and had no plans to marry soon.','他四十岁时仍未婚，也没有近期结婚的打算。','remain unmarried; unmarried person','形容词，指尚未结婚的。','the person has no spouse.','未婚'),M('He was unmarried at forty and had been married to the same person for twenty years.','He was unmarried at forty and had never married.','unmarried表示未婚，与已婚二十年相矛盾。','meaning'),[Q(1,'An unmarried person is…','not married','married to a spouse','not allowed by law to marry','That is the word meaning.','meaning'),Q(1,'What was his situation at forty?','He had not married and did not plan to soon','He had been married for twenty years','He was applying to a university','The context gives his marital status.','context'),Q(1,'Which phrase is natural?','remain unmarried','remain unmarriage','remain unmarriedly','Unmarried follows remain as an adjective.','grammar'),Q(1,'The prefix un- in unmarried means…','not married','married again','married by law','It negates married.','word-formation')]);
P('unmask','Unmask combines un- with mask; it means remove a mask to reveal a face, or expose a hidden identity, motive, or wrongdoing.',[C('unmask.s1','揭下面具','The villain unmasked himself in front of the crowd at the end of the play.','戏剧结尾，反派当着人群揭下了面具。','unmask oneself; unmask a performer','动词，指摘下面具露出真实面貌。','the hidden face becomes visible.','揭下面具'),C('unmask.s2','揭露真相','The audit unmasked the fraud behind the project and traced the false invoices.','审计揭露了项目背后的欺诈，并追查了虚假发票。','unmask a fraud/plot; unmask someone as','动词，比喻揭示隐藏的真实身份或不法行为。','the audit exposes wrongdoing that was concealed.','揭露真相')],M('The audit unmasked the fraud by hiding the false invoices more carefully.','The audit unmasked the fraud by exposing the false invoices.','unmask表示揭露隐藏的欺诈，掩盖证据与此相反。','meaning'),[Q(1,'The villain unmasked himself means he…','removed the mask from his face','put on a second mask','left the stage without revealing himself','Sense 1 is literal.','meaning'),Q(2,'The audit unmasked the fraud means it…','revealed wrongdoing that had been hidden','concealed the false invoices','approved the project without checking','Sense 2 is figurative exposure.','context'),Q(1,'Which phrase is natural?','unmask the person behind the account','unmask behindly the account person','unmask the account by behind','Behind identifies the concealed person.','grammar'),Q(1,'The prefix un- in unmask suggests…','removing what hides the face or truth','masking something again','making a mask for someone','Unmask reverses the act of masking.','word-formation')]);
P('unmatched','Unmatched is formed from un- plus matched; it can mean without an equal in quality or without a corresponding partner or item.',C('unmatched.s1','无与伦比/未配对','The collection is unmatched in East Asia, and one unmatched earring remained in the display case.','这批藏品在东亚无与伦比，展示柜里还剩下一只没有配对的耳环。','unmatched quality/skill; an unmatched pair','形容词，指品质无可比拟，也可指没有与之配对的。','the collection has no equal, while one earring lacks its mate.','无与伦比/未配对'),M('The collection is unmatched in East Asia because many museums have identical collections of equal quality.','The collection is unmatched in East Asia because no other collection equals its quality.','unmatched表示没有同等对象，而非许多收藏都完全相同。','meaning'),[Q(1,'An unmatched collection in quality is…','without an equal','identical to every other collection','not catalogued by a museum','That is the first sense.','meaning'),Q(1,'An unmatched earring is…','missing its corresponding partner','already paired with an identical earring','unusually famous','The context also illustrates the literal pairing sense.','context'),Q(1,'Which phrase is natural?','an unmatched level of skill','a skill unmatchedly level','a level of skill unmatch','Unmatched is an adjective modifying level.','grammar'),Q(1,'The prefix un- in unmatched means…','not matched or without an equal','matched several times','matched in the future','It negates the state of being matched.','word-formation')]);
P('unmistakable','Unmistakable is formed from un- plus mistakable, from mistake; it describes something so clear or distinctive that it cannot be confused with anything else.',C('unmistakable.s1','明显特征','There was an unmistakable smell of gas in the kitchen, so everyone left the building.','厨房里有明显的煤气味，因此所有人都离开了大楼。','unmistakable sign/smell; unmistakable evidence','形容词，指清楚、鲜明到不可能认错的。','the odor clearly identifies a gas leak.','明显'),M('There was an unmistakable smell of gas, but nobody could tell whether any odor was present.','There was an unmistakable smell of gas that everyone recognized immediately.','unmistakable表示特征鲜明、很容易辨认，不是无法判断有没有气味。','meaning'),[Q(1,'An unmistakable smell is…','so clear that it cannot be confused with another smell','so faint that nobody can detect it','a smell that changes every second','That is the adjective meaning.','meaning'),Q(1,'What did people do after smelling gas?','They left the building','They stayed in the kitchen','They joined a union','The context gives their safety response.','context'),Q(1,'Which phrase is natural?','an unmistakable sign of smoke','an unmistakably sign of smoke','a sign unmistakable of smoke','Unmistakable is an adjective before sign.','grammar'),Q(1,'The prefix un- in unmistakable means…','not able to be mistaken','likely to be mistaken','mistaken in the past','It marks something that cannot be confused.','word-formation')]);
P('unmixed','Unmixed is formed from un- plus mixed; it means not combined with anything else, or complete and not blended with another feeling or quality.',[C('unmixed.s1','未混合','Pour the unmixed juice into a clean glass before adding sparkling water.','加入气泡水前，把未混合的果汁倒进干净的玻璃杯。','unmixed ingredients/liquid; keep something unmixed','形容词，指没有与其他物质混合的。','the juice is still separate before dilution.','未混合'),C('unmixed.s2','纯粹的感情','She felt unmixed joy at the good news, with no trace of worry or regret.','听到好消息时，她感到纯粹的喜悦，没有一丝担忧或遗憾。','unmixed pleasure/joy; unmixed satisfaction','形容词，指感情纯粹，没有与其他感受掺杂。','the emotion is complete and unqualified.','纯粹')],M('Pour the unmixed juice into the glass after blending it thoroughly with water.','Pour the unmixed juice into the glass before combining it with water.','unmixed表示尚未混合，彻底加水搅拌后就不再是未混合状态。','meaning'),[Q(1,'Unmixed juice is…','not combined with another liquid','already blended thoroughly with water','a drink served by a tutor','Sense 1 is literal.','meaning'),Q(2,'Unmixed joy is…','complete joy without another feeling mixed in','joy combined with strong regret','a mixture of juice and water','Sense 2 is figurative.','context'),Q(1,'Which phrase is natural?','unmixed ingredients','ingredients unmixedly','an unmixed of ingredients','Unmixed modifies ingredients.','grammar'),Q(1,'The prefix un- in unmixed means…','not mixed','mixed again','mixed too much','It negates mixed.','word-formation')]);
P('unnamed','Unnamed is formed from un- plus named; it means not given a name, or not identified by name so the person or thing remains unknown.',[C('unnamed.s1','尚未命名','The village was still unnamed when the survey team first added it to the map.','测绘队首次把这个村庄标到地图上时，它还没有名字。','an unnamed village/road; remain unnamed','形容词，指尚未被命名的。','no name has yet been assigned to the place.','未命名'),C('unnamed.s2','未具名','An unnamed source gave the newspaper documents about the contract.','一名未具名消息人士向报纸提供了合同文件。','an unnamed source/official; remain unnamed','形容词，指姓名或身份没有公开确认的。','the source is not identified in the report.','未具名')],M('An unnamed source was quoted, and the article printed the sources full legal name.','An unnamed source was quoted without revealing the sources identity.','unnamed source指姓名未公开，刊出全名就不是未具名。','meaning'),[Q(1,'An unnamed village is…','a place that has not been given a name','a place whose name is printed on every map','a village governed by a union','Sense 1 is not yet named.','meaning'),Q(2,'An unnamed source in a newspaper is…','a person whose identity is not disclosed','a source whose name appears in the headline','a town not on a map','Sense 2 means unidentified by name.','context'),Q(1,'Which phrase is natural?','an unnamed official','an unnamedly official','an official unnamedness','Unnamed is an adjective before official.','grammar'),Q(1,'The prefix un- in unnamed…','negates named','means named twice','forms the verb name','It describes the absence of a name.','word-formation')]);
P('unnatural','Unnatural is formed from un- plus natural; it describes something contrary to nature or behavior that seems stiff and affected rather than sincere.',C('unnatural.s1','不自然','His laugh sounded unnatural, so his friend asked if something was wrong.','他的笑声听起来不自然，朋友便问他是不是出了什么事。','unnatural behavior/sound; feel unnatural','形容词，指不符合自然状态，或行为僵硬做作的。','the laugh does not sound sincere or spontaneous.','不自然'),M('His laugh sounded unnatural because it was warm, spontaneous, and completely sincere.','His laugh sounded unnatural because it was stiff and forced.','unnatural形容不自然或做作，真诚自然的笑声与之相反。','meaning'),[Q(1,'An unnatural laugh sounds…','stiff or affected','warm and spontaneous','like a unit of measurement','That is the behavioral sense.','meaning'),Q(1,'Why did the friend ask if something was wrong?','The laugh did not sound sincere','The friend heard a natural laugh','The room was uninhabited','The context gives the reason for concern.','context'),Q(1,'Which phrase is natural?','an unnatural pause in the conversation','an unnaturally pause in the conversation','a pause unnaturalness','Unnatural is an adjective before pause.','grammar'),Q(1,'The prefix un- in unnatural means…','not natural','natural again','very natural','It gives the opposite of natural.','word-formation')]);
P('unnaturally','Unnaturally is formed from unnatural plus -ly; it means in a way that is not natural or sincere.',C('unnaturally.s1','异常安静','The room was unnaturally quiet after the alarm stopped, and staff checked each floor.','警报停止后，房间里异常安静，工作人员检查了每一层。','unnaturally quiet/still; behave unnaturally','副词，指以不自然或异常的方式。','the silence is unusual enough to prompt a check.','异常地'),M('The room was unnaturally quiet, with a normal level of conversation and activity everywhere.','The room was unnaturally quiet because conversation and activity had stopped.','unnaturally quiet表示安静程度异常，正常热闹与之相反。','meaning'),[Q(1,'Unnaturally quiet means…','quieter than would normally be expected','exactly as loud as usual','quiet because everyone is asleep at home','That is the adverb meaning.','meaning'),Q(1,'What did the staff do?','They checked each floor','They turned the alarm back on','They closed the university','The context states their response to the unusual silence.','context'),Q(1,'Which phrase uses the adverb correctly?','The lights were unnaturally bright.','The unnaturally lights were bright.','The lights were unnatural bright.','Unnaturally modifies the adjective bright.','grammar'),Q(1,'Unnaturally is formed from…','unnatural plus -ly','natural plus the noun suffix -ness','unite plus -ation','The suffix forms an adverb.','word-formation')]);
P('unnecessarily','Unnecessarily is formed from unnecessary plus -ly; it means in a way that is not needed for the purpose or situation.',C('unnecessarily.s1','多余地','The process was unnecessarily complicated because three forms asked for the same information.','这个流程复杂得没有必要，因为三张表都在询问相同的信息。','unnecessarily complicated/expensive; criticize unnecessarily','副词，指没有必要地、超过实际所需地。','repeated forms add complexity without a useful purpose.','不必要地'),M('The process was unnecessarily complicated because every extra form served an essential purpose.','The process was unnecessarily complicated because the forms repeated information without need.','unnecessarily表示不必要地，若每个步骤都必不可少就不成立。','meaning'),[Q(1,'An unnecessarily complicated process…','has more complexity than the purpose requires','contains only essential steps','is impossible to understand for any reason','That is the adverb meaning.','meaning'),Q(1,'Why was the process unnecessarily complicated?','Three forms asked for the same information','Each form served a different purpose','The applicants were fully informed','The context identifies needless repetition.','context'),Q(1,'Which sentence uses unnecessarily correctly?','The report was unnecessarily long.','The unnecessarily report was long.','The report was unnecessary long.','The adverb modifies the adjective long.','grammar'),Q(1,'Unnecessarily is formed from…','unnecessary plus -ly','necessary plus -ful','unlawful plus -ness','The suffix changes the adjective into an adverb.','word-formation')]);
P('unnecessary','Unnecessary is formed from un- plus necessary; it means not needed for a purpose, or more than is needed and therefore removable.',[C('unnecessary.s1','非必需','There is no need to make unnecessary changes while the safety review is still in progress.','安全审查仍在进行时，没有必要做多余的改动。','unnecessary changes/costs; make something unnecessary','形容词，指为了当前目的并不需要的。','the changes are not required for the review.','非必需'),C('unnecessary.s2','多余','The second paragraph is unnecessary here because it repeats the same warning.','这里第二段是多余的，因为它重复了同一条警告。','an unnecessary paragraph/step; completely unnecessary','形容词，指超过所需、可以删去的。','the paragraph adds no new information.','多余')],M('The second paragraph was unnecessary, so the editor kept it even though it repeated the warning.','The second paragraph was unnecessary, so the editor removed the repeated warning.','不必要的段落因重复而可以删去，不应以此理由保留。','meaning'),[Q(1,'Unnecessary changes are…','changes not needed for the stated purpose','changes required by the safety review','changes that cannot be made','Sense 1 concerns need.','meaning'),Q(2,'Why was the second paragraph unnecessary?','It repeated the same warning','It added an essential new instruction','It introduced the only source','Sense 2 is excess that can be removed.','context'),Q(1,'Which phrase is natural?','an unnecessary step','an unnecessarily step','a step unnecessaryness','Unnecessary is an adjective modifying step.','grammar'),Q(1,'The prefix un- in unnecessary…','negates necessary','means necessary again','forms an adverb','It creates the negative adjective.','word-formation')]);
P('unnerve','Unnerve combines un- with nerve and means make someone lose confidence or courage, or make them feel worried, uncomfortable, or slightly frightened.',[C('unnerve.s1','使失去信心','The sudden silence unnerved the speaker, who forgot the next line of the presentation.','突然的沉默让演讲者失去信心，一时忘了演示的下一句。','unnerve a speaker; be unnerved by','动词，指使某人失去行动所需的信心或勇气。','the speaker loses confidence and hesitates.','使失去信心'),C('unnerve.s2','使不安','The empty house unnerved her after dark, even though every door was locked.','天黑后，空房子让她感到不安，尽管每扇门都锁好了。','unnerve someone; find something unnerving','动词，指使人担忧、不舒服或略感害怕。','the deserted setting makes her uneasy.','使不安')],M('The sudden silence unnerved the speaker, giving him complete confidence and helping him deliver the speech smoothly.','The sudden silence unnerved the speaker, making him lose confidence and forget his next line.','unnerve表示使人失去信心，与增强信心并帮助顺利演讲相反。','meaning'),[Q(1,'The silence unnerved the speaker means it…','made the speaker lose confidence','made the speaker feel more confident','made the speaker join a union','Sense 1 concerns courage.','meaning'),Q(2,'Why did the empty house unnerve her?','It made her feel uneasy after dark','It was full of friendly people','It gave her a university degree','Sense 2 is anxiety or fear.','context'),Q(1,'Which phrase is natural?','the thought unnerved her','the thought unnerving her was','the thought was unnervely','Unnerved takes the affected person as its object.','grammar'),Q(1,'Unnerve is formed from…','un- plus nerve','nerve plus the plural -s','universe plus -al','The verb means taking away someone nerves or courage.','word-formation')]);
P('unnoticeable','Unnoticeable is formed from un- plus noticeable; it means so slight or hidden that people are not likely to notice it.',C('unnoticeable.s1','不易察觉','The repair is almost unnoticeable because the new paint matches the old wall exactly.','这处修补几乎看不出来，因为新漆与旧墙完全匹配。','almost/completely unnoticeable; an unnoticeable change','形容词，指不太可能被人注意到的。','the matching paint conceals the repair.','不易察觉'),M('The repair was unnoticeable, marked by a bright red patch that every visitor spotted immediately.','The repair was unnoticeable because its paint matched the wall.','鲜红色且人人立刻发现的修补显然很容易被注意到。','meaning'),[Q(1,'An unnoticeable repair is…','not likely to attract attention','immediately visible to everyone','a repair that is against the law','That is the adjective meaning.','meaning'),Q(1,'Why was the repair hard to see?','The new paint matched the old wall','The new paint was bright red','The wall had no paint','The context explains why it escaped notice.','context'),Q(1,'Which phrase is natural?','an unnoticeable difference','an unnoticeably difference','a difference unnoticeablely','Unnoticeable is an adjective modifying difference.','grammar'),Q(1,'The prefix un- in unnoticeable means…','not noticeable','noticeable again','very noticeable','It negates noticeable.','word-formation')]);
P('unnoticed','Unnoticed is formed from un- plus noticed; it means not seen or realized, or happening without anyone paying attention.',[C('unnoticed.s1','未被发现','The change in the rules went unnoticed until the first group submitted its forms.','规则的变化一直没有被发现，直到第一组人提交了表格。','go unnoticed; remain unnoticed','形容词，指没有被人看到或意识到的。','nobody recognized the rule change at first.','未被发现'),C('unnoticed.s2','不知不觉','The hours passed unnoticed in the library while she revised her thesis.','她在图书馆修改论文时，几个小时不知不觉就过去了。','pass unnoticed; slip by unnoticed','形容词，指某事发生或结束时没有引起注意。','the reader was so absorbed that she did not notice time passing.','不知不觉')],M('The rule change went unnoticed, and every reader immediately pointed it out.','The rule change went unnoticed until someone later discovered it.','went unnoticed表示没有被注意到，所有人立刻指出就不是未被察觉。','meaning'),[Q(1,'A rule change went unnoticed means…','people did not see or realize it','everyone immediately discussed it','it was formally approved','Sense 1 concerns awareness.','meaning'),Q(2,'The hours passed unnoticed means…','time went by without her paying attention','she watched every minute carefully','the library closed after one hour','Sense 2 is time passing without notice.','context'),Q(1,'Which phrase is natural?','the error went unnoticed','the error went unnoticely','the unnoticed went error','Unnoticed follows went as a complement.','grammar'),Q(1,'The prefix un- in unnoticed means…','not noticed','noticed again','noticed by everyone','It negates noticed.','word-formation')]);
P('unobservable','Unobservable is formed from un- plus observable; it describes something impossible to detect directly with available observation.',C('unobservable.s1','科学观察','Dark matter is unobservable except through its gravitational effects on visible objects.','除了通过它对可见物体的引力作用，人们无法直接观测暗物质。','unobservable particle; remain unobservable','形容词，指不能被直接观察到的。','scientists infer it from indirect effects.','无法直接观测'),M('Dark matter is unobservable, and scientists photograph it directly with the naked eye.','Dark matter is unobservable directly, so scientists study its indirect effects.','unobservable表示无法直接观测，肉眼直接拍摄与此矛盾。','meaning'),[Q(1,'Unobservable directly means…','it cannot be detected by direct observation','it is visible to the naked eye','it has no effects at all','That is the word meaning.','meaning'),Q(1,'How do scientists study dark matter in the example?','Through its gravitational effects','By viewing it directly','By measuring a uniform','The context explains indirect evidence.','context'),Q(1,'Which phrase is natural?','an unobservable effect','an unobservably effect','an effect unobserve','Unobservable modifies effect.','grammar'),Q(1,'The prefix un- in unobservable…','negates observable','means observable again','marks a completed observation','It makes the adjective negative.','word-formation')]);
P('unobstructed','Unobstructed is formed from un- plus obstructed; it means free from anything that blocks passage, access, or sight.',C('unobstructed.s1','视线','The window gives an unobstructed view of the bay because no buildings stand in front of it.','窗外没有建筑遮挡，因此从窗户可以毫无遮挡地看到海湾。','unobstructed view/access; keep a path unobstructed','形容词，指没有东西妨碍视线或通行的。','nothing blocks the view through the window.','无遮挡'),M('The window gave an unobstructed view of the bay, although a tall wall covered the entire window.','The window gave an unobstructed view because nothing blocked the sightline.','墙挡住全部窗户就不能称为视线无遮挡。','meaning'),[Q(1,'An unobstructed view is…','a view with nothing blocking it','a view hidden by a tall wall','a view available only from underground','That is the adjective meaning.','meaning'),Q(1,'Why was the bay visible from the window?','No buildings stood in front of it','A wall covered the glass','The bay was inside the room','The context explains the clear sightline.','context'),Q(1,'Which phrase is natural?','an unobstructed path to the door','an unobstructedly path','a path obstructed un','Unobstructed is an adjective describing the path.','grammar'),Q(1,'The prefix un- in unobstructed means…','free from obstruction','blocked again','partly obstructed','It negates obstructed.','word-formation')]);
P('unobtainable','Unobtainable is formed from un- plus obtainable; it means not able to be acquired or secured.',C('unobtainable.s1','无法取得','Spare parts for the discontinued model are now unobtainable, so the repair shop offered a replacement.','这款停产型号的备用零件如今已无法取得，因此维修店提供了替代品。','unobtainable item/record; become unobtainable','形容词，指无法获得或取得的。','the discontinued parts can no longer be sourced.','无法取得'),M('The spare parts were unobtainable, but the repair shop ordered a full set from its supplier.','The spare parts were unobtainable, so the shop could not order them from any supplier.','unobtainable表示无法取得；成功订购一整套与此矛盾。','meaning'),[Q(1,'Unobtainable parts are…','not able to be acquired','available from every supplier','already installed in the machine','That is the adjective meaning.','meaning'),Q(1,'What did the repair shop offer?','A replacement for the unavailable parts','A full set of the original parts','A new university course','The context states the alternative.','context'),Q(1,'Which phrase is natural?','the parts are unobtainable','the parts unobtainably are','the unobtainable of parts','Unobtainable follows are as an adjective complement.','grammar'),Q(1,'The prefix un- in unobtainable means…','not able to be obtained','obtained again','obtained by one person','It negates obtainable.','word-formation')]);
P('unobtrusive','Unobtrusive is formed from un- plus obtrusive, ultimately from Latin obtrudere, “thrust forward”; it describes something quiet that does not attract attention or cause annoyance.',C('unobtrusive.s1','低调设备','The microphones are small and unobtrusive, so guests soon forget that they are recording.','这些麦克风体积小、不惹眼，客人很快就忘了它们正在录音。','unobtrusive design/equipment; remain unobtrusive','形容词，指安静、不引人注意或不造成打扰的。','the devices do their job without drawing attention.','不显眼'),M('The microphones were unobtrusive, with bright lights and loud alarms drawing every guests attention.','The microphones were unobtrusive because their small design did not distract the guests.','明亮灯光和响亮警报会引人注意，与unobtrusive相反。','meaning'),[Q(1,'Unobtrusive microphones are…','quiet and not likely to attract attention','large and distracting','unable to record sound','That is the adjective meaning.','meaning'),Q(1,'Why did guests forget the microphones?','They were small and did not distract','They had bright flashing lights','They interrupted every conversation','The context shows their low-key design.','context'),Q(1,'Which phrase is natural?','an unobtrusive design','an unobtrusively design','a design unobtrusion','Unobtrusive modifies the noun design.','grammar'),Q(1,'The Latin source obtrudere meant…','thrust forward','not obtain','pass unnoticed','Unobtrusive describes the opposite of thrusting itself forward.','word-formation')]);
P('unoccupied','Unoccupied is formed from un- plus occupied; it means not in use or not lived in at the moment, or not busy and free from work.',[C('unoccupied.s1','空位/空房','We found an unoccupied seat near the door after the first lecture ended.','第一场讲座结束后，我们在门边找到了一个空座位。','unoccupied seat/room; leave a place unoccupied','形容词，指当时无人使用或居住的。','nobody is using the seat at that time.','空置'),C('unoccupied.s2','有空','The manager was unoccupied for the whole afternoon and could review the new schedule.','经理整个下午都没有工作安排，可以查看新的日程。','remain unoccupied; otherwise unoccupied','形容词，指当时没有工作或职责要处理的。','the manager has no duties during that period.','有空')],M('We found an unoccupied seat, with another passenger already sitting in it.','We found an unoccupied seat that no passenger was using.','unoccupied seat指无人使用的座位，已有乘客坐着与之矛盾。','meaning'),[Q(1,'An unoccupied seat is…','not being used by anyone at the moment','reserved and already taken','broken and impossible to sit on','Sense 1 concerns use.','meaning'),Q(2,'The manager was unoccupied means…','the manager had no work or duty then','the manager was busy in several meetings','the manager lived in the office','Sense 2 is lack of current duties.','context'),Q(1,'Which phrase is natural?','an unoccupied room','an unoccupy room','a room unoccupiedly','Unoccupied modifies room.','grammar'),Q(1,'The prefix un- in unoccupied means…','not occupied','occupied again','occupied by many people','It negates occupied.','word-formation')]);
P('unpack','Unpack combines un- with pack; it means remove items from luggage or a package, and can also mean explain a complex idea piece by piece.',[C('unpack.s1','打开行李','We unpacked our suitcases before looking for a restaurant near the hotel.','我们先打开行李箱整理物品，然后才去酒店附近找餐馆。','unpack a suitcase/box; unpack the groceries','动词，指从箱子、行李或包装中取出物品。','the travellers remove their belongings from luggage.','拆包'),C('unpack.s1','逐步解释','The lecturer unpacked the complex theory by defining each term and showing an example.','讲师逐一解释术语并展示例子，把复杂理论分步骤讲清楚。','unpack an argument/idea; unpack a concept','动词，比喻分解复杂想法并逐步解释。','the explanation breaks the theory into understandable parts.','逐步解释')],M('We unpacked our suitcases by placing all our clothes back inside and closing them.','We unpacked our suitcases by taking our clothes out and arranging them in the room.','unpack行李是取出物品，而不是重新装回箱中。','meaning'),[Q(1,'To unpack a suitcase is to…','take items out of it','put all items into it and close it','send it to a university','Sense 1 is literal.','meaning'),Q(1,'The lecturer unpacked a theory by…','explaining its parts one by one','hiding all of its terms','putting the theory in a suitcase','Sense 2 is figurative explanation.','context'),Q(1,'Which phrase is natural?','unpack the argument step by step','unpack the argument into a suitcase','unpackedly the argument','The object is the idea being explained.','grammar'),Q(1,'The prefix un- in unpack indicates…','reversing the act of packing','packing again','making a package larger','It describes opening or taking apart what was packed.','word-formation')]);
P('unpaid','Unpaid is formed from un- plus paid; it describes money still owed, a bill or rent not paid by its due date, or work done without wages.',[C('unpaid.s1','未付款','The invoice is still unpaid after three months, so the supplier sent a reminder.','发票三个月后仍未付款，因此供应商发来了提醒。','unpaid invoice/bill; remain unpaid','形容词，指款项尚未支付、仍然欠着的。','the supplier has not received the money.','未付款'),C('unpaid.s2','逾期欠款','The rent is unpaid again this month, although the due date passed last Friday.','这个月房租又逾期未交，尽管上周五已过缴费期限。','unpaid rent/tax; leave an account unpaid','形容词，指到期应付款项尚未缴纳的。','the rent remains owed after its deadline.','逾期未交'),C('unpaid.s3','无薪的','She spent a year in unpaid volunteer work at the animal shelter.','她在动物收容所做了一年无薪志愿工作。','unpaid work/leave; an unpaid internship','形容词，指工作没有报酬的。','the volunteer receives no wages for the work.','无薪')],M('She accepted an unpaid volunteer position and received a large salary every month.','She accepted an unpaid volunteer position and received no wages for the work.','unpaid work没有工资，领取月薪与此相反。','meaning'),[Q(1,'An unpaid invoice is…','money that is still owed','an invoice settled in full','a bill that has not been issued','Sense 1 is outstanding money.','meaning'),Q(2,'The rent is unpaid after its due date means…','the required payment was not made on time','the rent was paid early','the tenant owes no rent','Sense 2 emphasizes overdue payment.','context'),Q(3,'Unpaid volunteer work is…','work done without wages','work with an unusually high salary','a job that no one performs','Sense 3 is unpaid labor.','meaning'),Q(1,'Which phrase is natural?','an unpaid internship','an unpaidly internship','an internship without unpaid','Unpaid is the adjective modifying internship.','grammar')]);
P('unpaid worker','Unpaid worker is a noun phrase formed from unpaid plus worker; it means a person who performs a job without receiving money for it.',C('unpaid worker.s1','志愿工作','The charity relies on every unpaid worker who helps sort donations on weekends.','这家慈善机构依靠每一位周末帮忙整理捐赠物品的无薪工作人员。','unpaid worker/volunteer; rely on unpaid workers','名词短语，指不因所做工作而领取报酬的人。','the worker contributes labor without wages.','无薪工作人员'),M('The charity relies on an unpaid worker who receives a full salary for sorting donations.','The charity relies on an unpaid worker who sorts donations without receiving wages.','unpaid worker指不领取工资的工作人员。','meaning'),[Q(1,'An unpaid worker is someone who…','does a job without receiving wages','receives a salary for every hour','works only as a university professor','That is the phrase meaning.','meaning'),Q(1,'What does the worker do for the charity?','Sort donations on weekends','Issue rent invoices','Unify two countries','The context describes the volunteer task.','context'),Q(1,'Which phrase is natural?','an unpaid worker at the charity','an unpaidly worker at charity','a worker unpaidness for charity','Unpaid modifies worker.','grammar'),Q(1,'Unpaid worker combines…','an adjective describing pay with a person doing a job','a unit of length with a workplace','university and a course section','The phrase describes the worker by payment status.','word-formation')]);
P('unpalatable','Unpalatable is formed from un- plus palatable, related to palate; it means disagreeable in taste or hard to accept because a conclusion is unpleasant.',[C('unpalatable.s1','难吃','The medicine had an unpalatable bitter taste, so the child refused another spoonful.','这种药味道苦得难以下咽，孩子拒绝再喝一勺。','unpalatable food/taste; make something palatable','形容词，指味道令人不快、难以下咽的。','the bitter medicine tastes unpleasant.','难吃'),C('unpalatable.s1','难以接受','The inquiry reached an unpalatable conclusion: years of warnings had been ignored.','调查得出一个令人难以接受的结论：多年来的警告一直被忽视。','an unpalatable truth/conclusion; face an unpalatable fact','形容词，比喻指令人不快、难以接受的事实或结论。','the finding is disturbing even though the evidence supports it.','难以接受')],M('The medicine had an unpalatable taste, and the child happily asked for a second spoonful.','The medicine had an unpalatable bitter taste, and the child refused another spoonful.','unpalatable指味道难吃，与愉快地要求再喝相反。','meaning'),[Q(1,'An unpalatable medicine tastes…','disagreeable or unpleasant','sweet and pleasant','exactly like water','Sense 1 concerns flavor.','meaning'),Q(1,'Why was the inquiry conclusion unpalatable?','It showed years of warnings had been ignored','It proved every warning was followed','It announced a popular prize','Sense 2 is a difficult truth to accept.','context'),Q(1,'Which phrase is natural?','an unpalatable truth','an unpalatably truth','a truth unpalatablely','Unpalatable is an adjective before truth.','grammar'),Q(1,'Palatable is related to the word…','palate','unpaid','parallel','The word concerns what the palate can accept.','word-formation')]);
P('unparalleled','Unparalleled is formed from un- plus paralleled; it means better than anything of its kind or without an equal in size, amount, or extent.',[C('unparalleled.s1','卓越','The pianist gave a performance of unparalleled beauty at the restored concert hall.','这位钢琴家在修复后的音乐厅献上了美得无与伦比的演奏。','unparalleled beauty/skill; of unparalleled quality','形容词，指在同类中极为出众、没有可比者的。','no other performance equals its quality.','无与伦比'),C('unparalleled.s2','规模空前','The project achieved unparalleled success, attracting more visitors than any earlier campaign.','该项目取得了空前成功，吸引的游客超过以往任何一次活动。','unparalleled growth/success; an unparalleled scale','形容词，指规模、数量或程度没有先例或匹敌者。','the number of visitors exceeds all previous campaigns.','空前')],M('The pianist gave an unparalleled performance, but every earlier performance was more beautiful.','The pianist gave an unparalleled performance that no earlier performance equaled.','unparalleled表示无可匹敌，若之前的演出更出色就不符合。','meaning'),[Q(1,'A performance of unparalleled beauty is…','better than any comparable performance','equal to every earlier performance','not heard by an audience','Sense 1 is exceptional quality.','meaning'),Q(2,'Unparalleled success in the example means…','more visitors came than in earlier campaigns','fewer people attended than ever before','the project did not attract visitors','Sense 2 concerns unprecedented scale.','context'),Q(1,'Which phrase is natural?','unparalleled success','unparalleledly success','success with no paralleledly','Unparalleled modifies the noun success.','grammar'),Q(1,'The prefix un- in unparalleled means…','without an equal or match','matched with another item','matched in advance','It negates being paralleled or equaled.','word-formation')]);
P('unpaved','Unpaved is formed from un- plus paved; it describes a road or surface covered with earth or gravel rather than paving material.',C('unpaved.s1','道路','The last mile to the cabin is an unpaved track with loose gravel and shallow ruts.','通往小屋的最后一英里是一条未铺路面的土路，有松散的碎石和浅车辙。','unpaved road/track; an unpaved surface','形容词，指表面没有铺设沥青、石块等路面材料的。','the track is made of earth and gravel.','未铺路面'),M('The unpaved track was covered with smooth asphalt and freshly painted road markings.','The unpaved track was made of earth and gravel without an asphalt surface.','unpaved表示没有铺设硬质路面，与平整沥青路相反。','meaning'),[Q(1,'An unpaved track has…','an earth or gravel surface','a smooth asphalt surface','a painted indoor floor','That is the adjective meaning.','meaning'),Q(1,'What is the final mile like?','Loose gravel with shallow ruts','Fresh asphalt and road markings','An unobstructed view of the bay','The context describes the rough road.','context'),Q(1,'Which phrase is natural?','an unpaved road','an unpavely road','an unpavedly road','Unpaved is an adjective before road.','grammar'),Q(1,'The prefix un- in unpaved means…','not paved','paved again','paved by a worker','It negates paved.','word-formation')]);
P('unplanned','Unplanned is formed from un- plus planned; it means not arranged in advance or happening because of a sudden wish rather than a prior plan.',[C('unplanned.s1','意外停留','An unplanned stop at the repair shop cost us an extra hour on the journey.','旅途中一次计划外的修理店停留让我们多花了一个小时。','unplanned stop/change; an unplanned event','形容词，指事先没有安排或打算的。','the travelers had not intended to stop.','计划外'),C('unplanned.s2','临时起意','They dropped in for an unplanned visit after seeing the lights on in the house.','他们看到屋里亮着灯，便临时起意进去拜访。','unplanned visit/trip; make an unplanned decision','形容词，指因一时想法而发生、没有预先计划的。','the visit is decided spontaneously.','临时起意')],M('The unplanned stop had been booked into the itinerary months in advance.','The unplanned stop was not included in the itinerary before the journey.','unplanned指未预先安排，提前数月列入行程便是计划好的。','meaning'),[Q(1,'An unplanned stop is…','a stop not arranged before it happened','a stop booked months earlier','a stop required by a written schedule','Sense 1 concerns advance arrangements.','meaning'),Q(2,'Why did they make an unplanned visit?','They saw the lights and decided to drop in','They had booked the visit a year ago','They were paid workers at the house','Sense 2 is a spontaneous decision.','context'),Q(1,'Which phrase is natural?','an unplanned change','an unplanning change','a change unplannedly','Unplanned is an adjective modifying change.','grammar'),Q(1,'The prefix un- in unplanned means…','not planned in advance','planned again','planned by one person only','It negates planned.','word-formation')]);
P('unpleasant','Unpleasant is formed from un- plus pleasant; it describes an experience that causes discomfort or upset, a disgusting smell or taste, or an unattractive appearance.',[C('unpleasant.s1','不愉快','She had an unpleasant surprise waiting at home when she discovered the broken window.','她回到家后发现窗户被打破，遇到了令人不快的意外。','unpleasant surprise/experience; find something unpleasant','形容词，指让人感到不舒服、烦恼或不愉快的。','the damage upsets the homeowner.','不愉快'),C('unpleasant.s2','难闻','The milk had an unpleasant smell, so we checked the date and threw it away.','牛奶有一股难闻的气味，因此我们查看日期后把它倒掉了。','unpleasant smell/taste; smell unpleasant','形容词，指气味或味道令人恶心的。','the odor suggests the milk may have spoiled.','难闻'),C('unpleasant.s3','难看','The room was lit by an unpleasant grey light that made the walls look harsh.','房间里是难看的灰色灯光，使墙面看起来很刺眼。','unpleasant appearance/light; look unpleasant','形容词，指外观看起来不舒服或刺眼的。','the color and lighting are unattractive.','难看')],M('The milk had an unpleasant smell, but everyone found its odor fresh and delightful.','The milk had an unpleasant smell, so we checked whether it had spoiled.','unpleasant smell令人不快，与新鲜怡人的气味相反。','meaning'),[Q(1,'An unpleasant surprise is…','an upsetting or uncomfortable experience','a welcome event that delights everyone','a smell that cannot be detected','Sense 1 concerns experience.','meaning'),Q(2,'Why was the milk discarded?','It had a disagreeable smell','It had no smell at all','It was an unplanned visit','Sense 2 is sensory dislike.','context'),Q(3,'An unpleasant grey light is…','visually harsh or unattractive','a pleasant bright color','a smell in the milk','Sense 3 concerns appearance.','meaning'),Q(1,'Which phrase is natural?','an unpleasant experience','an unpleasantly experience','an experience unpleasantness','Unpleasant is an adjective before experience.','grammar')]);
P('unplug','Unplug combines un- with plug; it means remove an electrical plug from its socket or clear a blockage in a pipe or drain.',[C('unplug.s1','拔插头/疏通','Unplug the kettle before cleaning it, and unplug the drain if water stops flowing.','清洁水壶前先拔掉插头；如果排水停止，也要疏通下水道。','unplug an appliance; unplug a drain','动词，指拔下电器插头，或清除管道中的堵塞物。','the appliance is disconnected, or the blocked drain is cleared.','拔插头/疏通')],M('Unplug the kettle before cleaning it, but leave its plug connected to the live socket.','Unplug the kettle before cleaning it by disconnecting it from the socket.','unplug电器就是拔掉插头，不是仍连接在通电插座上。','meaning'),[Q(1,'To unplug a kettle is to…','remove its plug from the socket','connect its plug to a live socket','fill its container with water','Sense 1 is the electrical use.','meaning'),Q(1,'To unplug a drain means to…','clear a blockage so water can flow','put an electrical cord into it','close the drain permanently','The source also uses unplug for removing a blockage.','context'),Q(1,'Which phrase is natural?','unplug the charger before cleaning','unplug the charger into the wall','unplug from the charger the wall to','Before introduces the time of disconnection.','grammar'),Q(1,'The prefix un- in unplug suggests…','removing or reversing the plug action','plugging something in again','making a plug larger','The verb describes taking a plug out or clearing a plug-like blockage.','word-formation')]);
P('unpopular','Unpopular is formed from un- plus popular; it means not liked, chosen, or supported by most people.',C('unpopular.s1','不受欢迎','The tax proved deeply unpopular because it raised costs for small businesses.','这项税收很不受欢迎，因为它提高了小企业的成本。','unpopular policy/decision; become unpopular','形容词，指不被大多数人喜欢或支持的。','the policy imposes costs on many businesses.','不受欢迎'),M('The tax was unpopular because nearly everyone praised it and asked for higher rates.','The tax was unpopular because it increased costs and drew public criticism.','unpopular表示不受支持；公众赞扬并要求提高税率与之相反。','meaning'),[Q(1,'An unpopular tax is…','not liked or supported by most people','supported enthusiastically by nearly everyone','a tax that has never been announced','That is the adjective meaning.','meaning'),Q(1,'Why was the tax unpopular?','It raised costs for small businesses','It reduced all business costs','It gave every firm a subsidy','The context gives the reason for public opposition.','context'),Q(1,'Which phrase is natural?','an unpopular policy','an unpopularly policy','a policy unpopularity','Unpopular is an adjective modifying policy.','grammar'),Q(1,'The prefix un- in unpopular means…','not popular','popular again','popular with one person only','It creates the opposite of popular.','word-formation')]);
P('unprecedented','Unprecedented is formed from un- plus precedented, from precedent; it means never known or done before, or greater or different than anything that came before.',[C('unprecedented.s1','前所未有','The storm caused unprecedented damage, closing roads that had never flooded before.','这场风暴造成了前所未有的损害，让从未被淹过的道路也关闭了。','unprecedented damage/event; at an unprecedented rate','形容词，指过去没有先例或没有发生过的。','the storm reaches places that had never flooded.','前所未有'),C('unprecedented.s2','超出以往','The growth is unprecedented, exceeding every previous annual increase in the region.','这次增长前所未有，超过了该地区以往每年的增幅。','unprecedented growth/success; an unprecedented level','形容词，指程度或规模超过此前任何情况的。','the increase is larger than all earlier ones.','超出以往')],M('The storm caused unprecedented damage, exactly matching the small losses recorded every year before.','The storm caused unprecedented damage, far exceeding all previous losses.','unprecedented表示没有先例或超过以往，完全相同于历年小损失不符。','meaning'),[Q(1,'Unprecedented damage is…','damage with no earlier comparable example','damage that occurs in the same small amount every year','damage that was planned in advance','Sense 1 emphasizes no previous case.','meaning'),Q(2,'The growth was unprecedented because it…','exceeded every earlier annual increase','matched the lowest previous increase','did not change at all','Sense 2 compares degree with earlier records.','context'),Q(1,'Which phrase is natural?','at an unprecedented rate','at an unprecedentedly rate','a rate unprecedentedness at','Unprecedented modifies rate.','grammar'),Q(1,'The prefix un- in unprecedented contributes…','the sense of no prior precedent','a repetition of an earlier event','a person who sets a precedent','It negates precedented.','word-formation')]);
P('unpredictability','Unpredictability is formed from unpredictable plus -ity; it means the state in which behavior or events cannot be forecast reliably.',C('unpredictability.s1','天气变化','The unpredictability of the weather ruined the schedule because storms arrived without warning.','天气变化难以预测，暴风雨毫无预警地到来，打乱了日程。','unpredictability of weather/behavior; cope with unpredictability','名词，指事件或行为无法被预先可靠预测的状态。','the timing of storms cannot be forecast.','不可预测性'),M('The unpredictability of the weather ruined the schedule, although every storm arrived exactly when forecast.','The unpredictability of the weather ruined the schedule because storms arrived without warning.','不可预测性表示无法提前预测，准确预报每场风暴与之相反。','meaning'),[Q(1,'Unpredictability of weather is…','the state of being unable to forecast it reliably','the certainty that storms will arrive on schedule','a period with no weather','That is the noun meaning.','meaning'),Q(1,'Why was the schedule ruined?','Storms arrived without warning','The forecasts were always exact','The team had unlimited time','The context links unpredictability to unannounced storms.','context'),Q(1,'Which phrase is natural?','the unpredictability of the weather','unpredictability weatherly of','the weather unpredictablyness','Of introduces what cannot be predicted.','grammar'),Q(1,'Unpredictability is formed from…','unpredictable plus -ity','predict plus the past-tense -ed','unpaid plus worker','The suffix forms a quality noun.','word-formation')]);
P('unpredictable','Unpredictable is formed from un- plus predictable; it means impossible to know or work out before something happens, or changing so often that others cannot rely on it.',[C('unpredictable.s1','难以预料','The weather here is wildly unpredictable, so hikers check several forecasts before setting out.','这里的天气极难预料，因此徒步者出发前会查看多个预报。','unpredictable result/weather; prove unpredictable','形容词，指事先无法知道或计算的。','the forecast may change before the hike.','难以预料'),C('unpredictable.s2','变化无常','An unpredictable temper made every meeting tense because colleagues could not guess his reaction.','他情绪变化无常，每次会议都很紧张，因为同事猜不出他的反应。','unpredictable behavior/temper; become unpredictable','形容词，指变化频繁，使人难以依赖或预料的。','his reaction changes from meeting to meeting.','变化无常')],M('The weather was unpredictable, so hikers knew with certainty that no forecast could ever change.','The weather was unpredictable, so hikers checked several forecasts before leaving.','unpredictable表示难以准确预料，确信预报绝不会变化与之相反。','meaning'),[Q(1,'Unpredictable weather is…','weather that cannot be forecast reliably','weather that always follows a fixed pattern','weather that is never observed','Sense 1 concerns forecasting.','meaning'),Q(2,'An unpredictable temper makes meetings tense because…','colleagues cannot anticipate the reaction','the person reacts the same way every time','the meetings are all canceled','Sense 2 is inconsistent behavior.','context'),Q(1,'Which phrase is natural?','an unpredictable result','an unpredictably result','a result unpredictability','Unpredictable is an adjective modifying result.','grammar'),Q(1,'The prefix un- in unpredictable…','negates predictable','means predictable again','makes a prediction in the past','It means the outcome cannot be reliably predicted.','word-formation')]);
P('unpredictably','Unpredictably is formed from unpredictable plus -ly; it means in a way that has no pattern allowing someone to know what will happen next.',C('unpredictably.s1','价格波动','Prices moved unpredictably all week, rising and falling without a clear pattern.','整个星期价格都难以预测地波动，涨跌没有明显规律。','move/change unpredictably; behave unpredictably','副词，指以没有可预知规律的方式发生。','the price changes cannot be forecast from a stable pattern.','难以预测地'),M('Prices moved unpredictably all week, following the same steady increase every morning.','Prices moved unpredictably all week, rising and falling without a stable pattern.','每天稳定上涨的价格走势有规律，不是unpredictably。','meaning'),[Q(1,'Prices moved unpredictably means…','their changes had no reliable pattern','they rose by the same amount every day','they never changed','That is the adverb meaning.','meaning'),Q(1,'What pattern did prices show?','They rose and fell without a clear pattern','They increased steadily each morning','They stayed fixed all week','The context contrasts irregular movement with a fixed pattern.','context'),Q(1,'Which sentence uses the adverb correctly?','The wind shifted unpredictably during the race.','The unpredictably wind shifted during the race.','The wind unpredictability shifted.','Unpredictably modifies the verb shifted.','grammar'),Q(1,'Unpredictably is formed from…','unpredictable plus -ly','predictability plus the plural -s','unplanned plus -ed','The suffix creates an adverb of manner.','word-formation')]);
})(typeof window!=='undefined'?window:globalThis);
